import { Flashcard } from "../types";

const source = "Science Olympiad official Anatomy & Physiology pages (soinc.org/anatomy-and-physiology-b and -c); OpenStax Anatomy and Physiology 2e";

const cards: Array<[string, string, string, string]> = [
  ["General", "What are the six levels of organization in the human body?", "Chemical, cellular, tissue, organ, organ system, and organismal.", "anatomy-1"],
  ["General", "What are the four primary tissue types?", "Epithelial, connective, muscle, and nervous tissue.", "anatomy-2"],
  ["General", "What is homeostasis?", "The maintenance of relatively stable internal conditions despite external change.", "anatomy-3"],
  ["General", "What are the components of a homeostatic control system?", "A receptor detects a stimulus, a control center compares it with a set point, and an effector produces a response.", "anatomy-4"],
  ["General", "What is negative feedback?", "A response reduces or reverses the original stimulus, helping keep a variable near its set point.", "anatomy-5"],
  ["General", "What is positive feedback?", "A response amplifies the original stimulus until a specific endpoint is reached, such as childbirth or clotting.", "anatomy-6"],
  ["General", "What do superior, inferior, anterior, and posterior mean?", "Superior is above, inferior below, anterior toward the front, and posterior toward the back.", "anatomy-7"],
  ["General", "What do proximal and distal mean?", "Proximal is nearer the point of attachment; distal is farther from it.", "anatomy-8"],
  ["General", "What do medial and lateral mean?", "Medial is toward the body's midline; lateral is away from the midline.", "anatomy-9"],
  ["General", "What are the three anatomical planes?", "Sagittal divides left and right, frontal/coronal divides anterior and posterior, and transverse divides superior and inferior.", "anatomy-10"],
  ["Cells", "What is the function of the plasma membrane?", "It forms a selective barrier that regulates movement between the cell and its environment.", "anatomy-11"],
  ["Cells", "What is diffusion?", "Net movement of particles down a concentration gradient, from higher to lower concentration.", "anatomy-12"],
  ["Cells", "What is osmosis?", "Diffusion of water across a selectively permeable membrane.", "anatomy-13"],
  ["Cells", "What is active transport?", "Movement across a membrane using cellular energy, usually against a concentration or electrochemical gradient.", "anatomy-14"],
  ["Cells", "What is the role of mitochondria?", "They generate most cellular ATP through aerobic cellular respiration.", "anatomy-15"],
  ["Cells", "What is the role of ribosomes?", "They assemble amino acids into polypeptides during protein synthesis.", "anatomy-16"],
  ["Cells", "What does the rough endoplasmic reticulum do?", "It synthesizes and begins processing proteins destined for secretion, membranes, or organelles.", "anatomy-17"],
  ["Cells", "What does the Golgi apparatus do?", "It modifies, sorts, and packages proteins and lipids for delivery.", "anatomy-18"],
  ["Cells", "What do lysosomes do?", "They use hydrolytic enzymes to digest macromolecules and worn cellular components.", "anatomy-19"],
  ["Cells", "What is apoptosis?", "Programmed, regulated cell death that removes cells without the typical inflammation of injury.", "anatomy-20"],
  ["Respiratory", "What is the primary function of the respiratory system?", "To exchange oxygen and carbon dioxide between the atmosphere and the body's tissues.", "anatomy-21"],
  ["Respiratory", "What is the path of air from the nose to the alveoli?", "Nasal cavity, pharynx, larynx, trachea, bronchi, bronchioles, and alveoli.", "anatomy-22"],
  ["Respiratory", "What is the function of the nasal cavity?", "It filters, warms, and humidifies incoming air and contains olfactory receptors.", "anatomy-23"],
  ["Respiratory", "What prevents food from entering the trachea?", "The epiglottis folds over the laryngeal opening during swallowing.", "anatomy-24"],
  ["Respiratory", "What is the role of cilia and mucus in the airways?", "Mucus traps particles and cilia move the mucus toward the pharynx for removal or swallowing.", "anatomy-25"],
  ["Respiratory", "What is the respiratory membrane?", "The thin barrier across which gases diffuse between alveolar air and pulmonary capillary blood.", "anatomy-26"],
  ["Respiratory", "Why are alveoli effective for gas exchange?", "They provide enormous surface area, thin walls, a moist surface, and a dense capillary network.", "anatomy-27"],
  ["Respiratory", "What drives oxygen diffusion from alveoli into blood?", "A higher oxygen partial pressure in alveolar air than in deoxygenated pulmonary capillary blood.", "anatomy-28"],
  ["Respiratory", "What drives carbon dioxide diffusion from blood into alveoli?", "A higher carbon dioxide partial pressure in pulmonary capillary blood than in alveolar air.", "anatomy-29"],
  ["Respiratory", "What is pulmonary ventilation?", "The movement of air into and out of the lungs: inspiration and expiration.", "anatomy-30"],
  ["Respiratory", "What muscle is most important for quiet inspiration?", "The diaphragm; its contraction flattens it and increases thoracic volume.", "anatomy-31"],
  ["Respiratory", "What is tidal volume?", "The amount of air moved into or out of the lungs during a normal quiet breath.", "anatomy-32"],
  ["Respiratory", "What is residual volume?", "The air remaining in the lungs after a maximal forced expiration.", "anatomy-33"],
  ["Respiratory", "How is most oxygen transported in blood?", "Bound reversibly to hemoglobin in red blood cells; a small amount is dissolved in plasma.", "anatomy-34"],
  ["Respiratory", "How is most carbon dioxide transported in blood?", "Primarily as bicarbonate ions, with smaller amounts bound to hemoglobin or dissolved in plasma.", "anatomy-35"],
  ["Digestive", "What are the major functions of the digestive system?", "Ingestion, propulsion, mechanical and chemical digestion, absorption, and defecation.", "anatomy-36"],
  ["Digestive", "What is the route of food through the alimentary canal?", "Mouth, pharynx, esophagus, stomach, small intestine, large intestine, rectum, and anus.", "anatomy-37"],
  ["Digestive", "What is peristalsis?", "Coordinated waves of smooth muscle contraction that propel contents through the digestive tract.", "anatomy-38"],
  ["Digestive", "What is the function of the stomach?", "It stores and churns food, begins protein digestion, and forms acidic chyme.", "anatomy-39"],
  ["Digestive", "What protects the stomach lining from its acid?", "A mucus-bicarbonate barrier, tight epithelial junctions, and rapid epithelial renewal.", "anatomy-40"],
  ["Digestive", "What are the three regions of the small intestine?", "Duodenum, jejunum, and ileum.", "anatomy-41"],
  ["Digestive", "Where does most nutrient absorption occur?", "Across the villi and microvilli of the small intestine.", "anatomy-42"],
  ["Digestive", "What is the function of intestinal villi and microvilli?", "They greatly increase surface area for digestion and absorption.", "anatomy-43"],
  ["Digestive", "What does bile do?", "It emulsifies dietary fats into smaller droplets, increasing access for lipase; it is not itself a digestive enzyme.", "anatomy-44"],
  ["Digestive", "Which organ produces bile?", "The liver produces bile; the gallbladder stores and concentrates it.", "anatomy-45"],
  ["Digestive", "What are the exocrine functions of the pancreas?", "It releases digestive enzymes and bicarbonate into the duodenum.", "anatomy-46"],
  ["Digestive", "What is the role of the large intestine?", "It absorbs water and electrolytes, compacts feces, and houses intestinal microbiota.", "anatomy-47"],
  ["Digestive", "What is mechanical digestion?", "Physical breakdown of food, such as chewing and stomach churning, without changing its chemical identity.", "anatomy-48"],
  ["Digestive", "What is chemical digestion?", "Enzymatic hydrolysis that breaks large food molecules into absorbable smaller molecules.", "anatomy-49"],
  ["Immune", "What are the two broad divisions of immunity?", "Innate immunity is immediate and nonspecific; adaptive immunity is specific and develops immunologic memory.", "anatomy-50"],
  ["Immune", "What are the first-line defenses of innate immunity?", "Physical and chemical barriers such as skin, mucous membranes, cilia, secretions, and the microbiota.", "anatomy-51"],
  ["Immune", "What are the cardinal signs of inflammation?", "Redness, heat, swelling, pain, and loss of function.", "anatomy-52"],
  ["Immune", "What is the purpose of inflammation?", "To contain injury or infection, recruit immune cells, remove damaged material, and begin repair.", "anatomy-53"],
  ["Immune", "What do neutrophils do?", "They rapidly migrate to sites of infection and phagocytose pathogens and debris.", "anatomy-54"],
  ["Immune", "What do macrophages do?", "They phagocytose pathogens and debris, release signals, and can present antigen to lymphocytes.", "anatomy-55"],
  ["Immune", "What are the main functions of complement?", "It can promote inflammation, opsonize pathogens, and form membrane attack complexes.", "anatomy-56"],
  ["Immune", "What is an antigen?", "A molecule or molecular region specifically recognized by an antibody or antigen receptor.", "anatomy-57"],
  ["Immune", "What do B cells do?", "They differentiate into plasma cells that secrete antibodies and memory B cells.", "anatomy-58"],
  ["Immune", "What do cytotoxic T cells do?", "They kill infected or abnormal host cells displaying appropriate antigen.", "anatomy-59"],
  ["Immune", "What is the difference between a vaccine and passive immunization?", "Vaccination stimulates the person's own adaptive response and memory; passive immunization supplies ready-made antibodies.", "anatomy-60"],
  ["Immune", "What is an antibody?", "An immunoglobulin made by plasma cells that binds a specific antigen and can neutralize or tag it.", "anatomy-61"],
  ["Immune", "What is immunologic memory?", "A faster and stronger response to a previously encountered antigen due to long-lived memory cells.", "anatomy-62"],
  ["Cardiovascular", "What are the four chambers of the heart?", "Right atrium, right ventricle, left atrium, and left ventricle.", "anatomy-63"],
  ["Cardiovascular", "What is the path of blood through the pulmonary circuit?", "Right ventricle to pulmonary arteries to lung capillaries to pulmonary veins to left atrium.", "anatomy-64"],
  ["Cardiovascular", "Why is the left ventricular wall thicker than the right?", "It pumps blood through the high-resistance systemic circuit, while the right ventricle pumps only to the lungs.", "anatomy-65"],
  ["Cardiovascular", "What prevents backflow through the heart valves?", "Pressure differences close the atrioventricular and semilunar valves after blood moves forward.", "anatomy-66"],
  ["Cardiovascular", "What is cardiac output?", "Heart rate multiplied by stroke volume; it is the volume pumped by one ventricle per minute.", "anatomy-67"],
  ["Cardiovascular", "What is blood pressure?", "The force exerted by circulating blood against the walls of blood vessels.", "anatomy-68"],
  ["Cardiovascular", "What is systolic versus diastolic pressure?", "Systolic pressure occurs during ventricular contraction; diastolic pressure occurs during ventricular relaxation.", "anatomy-69"],
  ["Cardiovascular", "What is the function of red blood cells?", "To transport oxygen and some carbon dioxide using hemoglobin.", "anatomy-70"],
  ["Cardiovascular", "What is the function of platelets?", "They adhere to damaged vessels and help form a platelet plug during hemostasis.", "anatomy-71"],
  ["Cardiovascular", "What is the normal direction of exchange at most systemic capillaries?", "Oxygen and nutrients leave blood while carbon dioxide and wastes enter blood, depending on gradients.", "anatomy-72"],
  ["Nervous", "What are the major divisions of the nervous system?", "The central nervous system is the brain and spinal cord; the peripheral nervous system contains nerves and ganglia.", "anatomy-73"],
  ["Nervous", "What is the function of a neuron?", "To receive, process, and transmit information using electrical and chemical signals.", "anatomy-74"],
  ["Nervous", "What is a synapse?", "A junction where a neuron communicates with another neuron, muscle cell, or gland cell.", "anatomy-75"],
  ["Nervous", "What is a neurotransmitter?", "A chemical messenger released by a neuron that binds receptors on a target cell.", "anatomy-76"],
  ["Nervous", "What is a reflex arc?", "A rapid pathway from sensory receptor through the nervous system to an effector, often without requiring conscious brain processing first.", "anatomy-77"],
  ["Nervous", "What is the autonomic nervous system?", "The division that regulates involuntary visceral functions such as heart rate, digestion, and gland activity.", "anatomy-78"],
  ["Muscular", "What are the three types of muscle tissue?", "Skeletal, cardiac, and smooth muscle.", "anatomy-79"],
  ["Muscular", "What is the sliding filament model?", "Myosin heads pull actin filaments toward the center of a sarcomere, shortening the muscle fiber.", "anatomy-80"],
  ["Muscular", "What roles do calcium and ATP play in contraction?", "Calcium exposes actin binding sites; ATP powers myosin cycling and allows myosin to detach.", "anatomy-81"],
  ["Muscular", "What is a prime mover?", "The muscle primarily responsible for producing a particular movement.", "anatomy-82"],
  ["Excretory", "What are the main functions of the urinary system?", "Excretion of wastes, regulation of water and electrolytes, acid-base balance, blood pressure, and hormone-related functions.", "anatomy-83"],
  ["Excretory", "What is the functional unit of the kidney?", "The nephron.", "anatomy-84"],
  ["Excretory", "What are the three basic nephron processes?", "Glomerular filtration, tubular reabsorption, and tubular secretion.", "anatomy-85"],
  ["Excretory", "Where does filtration occur?", "Across the glomerular filtration barrier from glomerular blood into Bowman's capsule.", "anatomy-86"],
  ["Excretory", "What does ADH do?", "It increases water reabsorption in collecting ducts, concentrating urine and reducing water loss.", "anatomy-87"],
  ["Integumentary", "What are the major functions of skin?", "Protection, temperature regulation, sensation, vitamin D production, limited excretion, and prevention of water loss.", "anatomy-88"],
  ["Integumentary", "What are the layers of the epidermis from deep to superficial?", "Stratum basale, spinosum, granulosum, lucidum where present, and corneum.", "anatomy-89"],
  ["Integumentary", "What is the role of melanin?", "It absorbs ultraviolet radiation and helps protect nuclear DNA in skin cells.", "anatomy-90"],
  ["Integumentary", "How does sweating cool the body?", "Evaporation of sweat from the skin removes heat from the body surface.", "anatomy-91"],
  ["Study Skills", "What materials does the official event page identify as useful preparation?", "The current rules and official event resources; the event may assess systems through questions, diagrams, stations, models, or calculations.", "anatomy-92"],
  ["Study Skills", "Why should you practice with diagrams and models?", "Anatomy tests commonly require rapid identification, labeling, and relating structure to function.", "anatomy-93"],
  ["Study Skills", "Why should current rules be checked before studying a system rotation?", "The official rules define the current Division B/C scope and can change from year to year.", "anatomy-94"],
  ["Study Skills", "What should a useful note sheet prioritize?", "Accurate, high-yield structures, functions, pathways, diagrams, formulas, and facts that are difficult to recall quickly.", "anatomy-95"],
  ["Forum Marathon", "Name three common skin cancers and rank them from most deadly to least deadly.", "Melanoma is generally the most deadly, followed by squamous cell carcinoma, then basal cell carcinoma. Individual outcomes vary, and early detection matters.", "anatomy-96"],
  ["Forum Marathon", "What is a ball-and-socket joint? Give two examples.", "A multiaxial synovial joint allowing flexion, extension, abduction, adduction, rotation, and circumduction; examples are the shoulder and hip.", "anatomy-97"],
  ["Forum Marathon", "What is a hinge joint? Give an example.", "A synovial joint that primarily permits flexion and extension in one plane; the elbow and interphalangeal joints are examples.", "anatomy-98"],
  ["Forum Marathon", "What is a pivot joint? Give an example.", "A synovial joint allowing rotation around one axis; the atlantoaxial joint and proximal radioulnar joint are examples.", "anatomy-99"],
  ["Forum Marathon", "What is a condyloid joint? Give an example.", "A biaxial synovial joint permitting flexion, extension, abduction, adduction, and circumduction; the metacarpophalangeal joint is an example.", "anatomy-100"],
  ["Forum Marathon", "What is a saddle joint? Give an example.", "A biaxial synovial joint whose surfaces are each concave in one direction and convex in another; the thumb carpometacarpal joint is an example.", "anatomy-101"],
  ["Forum Marathon", "What is a plane joint? Give an example.", "A synovial joint permitting mostly gliding movements; intercarpal and intertarsal joints are examples.", "anatomy-102"],
  ["Forum Marathon", "What is abduction?", "Movement of a body part away from the body's midline.", "anatomy-103"],
  ["Forum Marathon", "What is adduction?", "Movement of a body part toward the body's midline.", "anatomy-104"],
  ["Forum Marathon", "What is flexion?", "A movement that decreases the angle between bones at a joint.", "anatomy-105"],
  ["Forum Marathon", "What is extension?", "A movement that increases the angle between bones at a joint; hyperextension passes beyond anatomical position.", "anatomy-106"],
  ["Forum Marathon", "What is circumduction?", "A circular movement combining flexion, extension, abduction, and adduction so the distal end traces a circle.", "anatomy-107"],
  ["Forum Marathon", "What is rotation?", "Movement of a bone around its longitudinal axis, such as turning the head from side to side.", "anatomy-108"],
  ["Forum Marathon", "What is the difference between an organ and an organ system?", "An organ contains multiple tissue types performing a specific function; an organ system is a group of organs coordinating related functions.", "anatomy-109"],
  ["Forum Marathon", "Why are diagrams and models important in Anatomy & Physiology?", "The event can assess identification, labeling, location, and structure-function relationships using stations, models, diagrams, or slides.", "anatomy-110"],
  ["Forum Marathon", "What rotation was identified in a forum discussion as Respiratory, Digestive, and Immune?", "A forum rotation summary identified those three systems together for one prior season; always verify the current official rules before relying on a rotation.", "anatomy-111"],
  ["Forum Marathon", "What is the difference between the epidermis and dermis?", "The epidermis is the outer epithelial layer; the dermis is deeper connective tissue containing blood vessels, nerves, glands, and hair follicles.", "anatomy-112"],
  ["Forum Marathon", "Why is melanoma more dangerous than many other skin cancers?", "It arises from melanocytes and can metastasize aggressively; risk depends on tumor biology and stage, so suspicious lesions need medical evaluation.", "anatomy-113"],
  ["Forum Marathon", "What is a synovial joint?", "A freely movable joint with a joint cavity, articular cartilage, synovial membrane, and synovial fluid.", "anatomy-114"],
  ["Forum Marathon", "What does synovial fluid do?", "It lubricates the joint, reduces friction, and helps nourish the avascular articular cartilage.", "anatomy-115"],
  ["Forum Marathon", "What is the anatomical position?", "Standing upright, facing forward, feet together or parallel, arms at the sides, and palms facing forward.", "anatomy-116"],
  ["Forum Marathon", "What is ipsilateral versus contralateral?", "Ipsilateral means on the same side of the body; contralateral means on the opposite side.", "anatomy-117"],
  ["Forum Marathon", "What is the difference between visceral and parietal serous membranes?", "Visceral serosa covers an organ; parietal serosa lines the body cavity wall, with fluid between them reducing friction.", "anatomy-118"],
  ["Forum Marathon", "What is the difference between an endocrine and exocrine gland?", "Endocrine glands release hormones into interstitial fluid and blood; exocrine glands release products through ducts to a surface or lumen.", "anatomy-119"],
  ["Forum Marathon", "What is a receptor in a homeostatic feedback loop?", "A sensor that detects a change in a regulated variable and sends information to the control center.", "anatomy-120"],
  ["Forum Marathon", "Why should an Anatomy & Physiology answer include precise spelling?", "The event may grade labels and anatomical terms exactly; a correct concept with an ambiguous or misspelled structure name may not receive credit.", "anatomy-121"],
  ["General", "What is the difference between a body cavity and a membrane?", "A body cavity is a space that houses organs; a membrane is a tissue layer that covers organs, lines cavities, or reduces friction.", "anatomy-122"],
  ["General", "What is the serous membrane arrangement around a lung?", "The visceral pleura covers the lung, the parietal pleura lines the thoracic wall, and pleural fluid lies between them.", "anatomy-123"],
  ["General", "Why are epithelial tissues suited to lining surfaces?", "They form tightly connected sheets with little extracellular space, allowing protection, selective exchange, secretion, or absorption.", "anatomy-124"],
  ["General", "What is a tissue's extracellular matrix?", "Material outside cells, including protein fibers and ground substance, that supports, anchors, and influences connective-tissue cells.", "anatomy-125"],
  ["General", "What is the difference between an endocrine signal and a paracrine signal?", "Endocrine hormones travel through blood to distant targets; paracrine signals act on nearby cells.", "anatomy-126"],
  ["General", "What is an effector in homeostasis?", "A muscle, gland, or other tissue that carries out the control center's response to a detected change.", "anatomy-127"],
  ["General", "Why does negative feedback not mean a response is always negative or harmful?", "Negative describes the response's relationship to the stimulus: it opposes the deviation and stabilizes the regulated variable.", "anatomy-128"],
  ["General", "A patient's body temperature rises during a fever. Is that necessarily a failure of homeostasis?", "Not necessarily. A fever can involve a regulated upward set-point change; homeostatic mechanisms may still defend that new set point.", "anatomy-129"],
  ["Cells", "What is the sodium-potassium pump's net transport per ATP?", "It moves three Na+ out of the cell and two K+ into the cell per ATP hydrolyzed, contributing to membrane potential.", "anatomy-130"],
  ["Cells", "What is facilitated diffusion?", "Passive movement down a concentration or electrochemical gradient through a membrane channel or carrier, without direct ATP use.", "anatomy-131"],
  ["Cells", "What happens to an animal cell in a hypotonic solution?", "Water tends to enter by osmosis, so the cell swells and may lyse if the difference is large.", "anatomy-132"],
  ["Cells", "Why does a hypertonic solution shrink a cell?", "The solution has a lower effective water concentration, so water leaves the cell by osmosis.", "anatomy-133"],
  ["Cells", "What is the role of the nucleolus?", "It synthesizes rRNA and assembles ribosomal subunits inside the nucleus.", "anatomy-134"],
  ["Cells", "What is receptor-mediated endocytosis?", "Selective uptake in which ligand-bound receptors cluster in membrane-coated pits that bud inward as vesicles.", "anatomy-135"],
  ["Skeletal", "What are the major functions of the skeletal system?", "Support, protection, movement with muscles, mineral storage, blood-cell formation in marrow, and triglyceride storage in yellow marrow.", "anatomy-136"],
  ["Skeletal", "What is the difference between axial and appendicular skeletons?", "The axial skeleton forms the central axis of the body; the appendicular skeleton includes limbs and the pectoral and pelvic girdles.", "anatomy-137"],
  ["Skeletal", "What are the four bone cell types?", "Osteogenic cells, osteoblasts, osteocytes, and osteoclasts.", "anatomy-138"],
  ["Skeletal", "What do osteoblasts do?", "They secrete osteoid and promote bone formation; mature osteoblasts that become embedded are osteocytes.", "anatomy-139"],
  ["Skeletal", "What do osteoclasts do?", "They resorb bone by secreting acid and enzymes, helping remodel bone and release minerals.", "anatomy-140"],
  ["Skeletal", "What is compact bone organized into?", "Osteons, or Haversian systems, with concentric lamellae around a central canal.", "anatomy-141"],
  ["Skeletal", "What are trabeculae?", "Thin bony plates or struts that form the lattice of spongy bone and align with stresses.", "anatomy-142"],
  ["Skeletal", "What is the periosteum?", "A connective-tissue covering on the outer surface of bone, except where articular cartilage covers it.", "anatomy-143"],
  ["Skeletal", "What is endochondral ossification?", "Bone formation in which a hyaline cartilage model is gradually replaced by bone, as in most long bones.", "anatomy-144"],
  ["Skeletal", "What is intramembranous ossification?", "Bone formation directly within a connective-tissue membrane, used for many flat skull bones and part of the clavicle.", "anatomy-145"],
  ["Skeletal", "What is the epiphyseal plate?", "A layer of hyaline cartilage where a growing long bone lengthens; it becomes an epiphyseal line after growth.", "anatomy-146"],
  ["Skeletal", "What is Wolff's law?", "Bone remodels in response to mechanical loading, adding or resorbing tissue according to stresses placed on it.", "anatomy-147"],
  ["Skeletal", "Why does a fracture hematoma form?", "Broken blood vessels bleed into the injury site, producing a clot that provides a temporary framework for repair.", "anatomy-148"],
  ["Skeletal", "What is a comminuted fracture?", "A fracture in which the bone is broken or splintered into several fragments.", "anatomy-149"],
  ["Skeletal", "What is the difference between a ligament and a tendon?", "A ligament connects bone to bone and stabilizes joints; a tendon connects muscle to bone and transmits force.", "anatomy-150"],
  ["Skeletal", "What is a cartilaginous joint?", "A joint in which bones are connected by cartilage, allowing little or limited movement, such as a pubic symphysis.", "anatomy-151"],
  ["Skeletal", "What is a fibrous joint?", "A joint connected by dense connective tissue with no joint cavity, such as a skull suture.", "anatomy-152"],
  ["Skeletal", "Why does articular cartilage have limited healing capacity?", "It lacks its own blood vessels, so nutrients and repair cells must diffuse through surrounding tissues or synovial fluid.", "anatomy-153"],
  ["Skeletal", "What is a sprain versus a strain?", "A sprain injures a ligament; a strain injures a muscle or tendon.", "anatomy-154"],
  ["Skeletal", "A joint permits movement in two perpendicular axes but not rotation. What class is likely?", "A biaxial synovial joint, such as a condyloid or saddle joint, depending on its surface shape.", "anatomy-155"],
  ["Skeletal", "Why does osteoporosis increase fracture risk?", "Reduced bone mass and disrupted microarchitecture weaken the skeleton, so ordinary loads are more likely to cause fractures.", "anatomy-156"],
  ["Muscular", "What are the key differences among skeletal, cardiac, and smooth muscle?", "Skeletal muscle is striated and voluntary; cardiac muscle is striated, branched, and involuntary; smooth muscle is nonstriated and involuntary.", "anatomy-157"],
  ["Muscular", "What is a sarcomere?", "The contractile unit between two Z discs in striated muscle.", "anatomy-158"],
  ["Muscular", "What are the thick and thin filaments?", "Thick filaments contain myosin; thin filaments contain actin plus regulatory proteins such as troponin and tropomyosin.", "anatomy-159"],
  ["Muscular", "What happens to the A band during sarcomere contraction?", "Its length remains approximately constant because it corresponds to the length of thick filaments; the I band and H zone shorten.", "anatomy-160"],
  ["Muscular", "What is excitation-contraction coupling?", "A muscle action potential triggers calcium release, allowing actin-myosin interaction and force production.", "anatomy-161"],
  ["Muscular", "What does acetylcholinesterase do at the neuromuscular junction?", "It rapidly breaks down acetylcholine in the synaptic cleft, helping end the motor-neuron signal.", "anatomy-162"],
  ["Muscular", "What is a motor unit?", "One motor neuron and all the skeletal muscle fibers it controls.", "anatomy-163"],
  ["Muscular", "Why do small motor units support fine control?", "Each neuron activates fewer fibers, allowing smaller, more precise increments of force.", "anatomy-164"],
  ["Muscular", "What is summation in skeletal muscle?", "A stronger contraction produced when stimuli arrive before the muscle has fully relaxed, increasing cytosolic calcium and force.", "anatomy-165"],
  ["Muscular", "What is tetanus in muscle physiology?", "A sustained contraction caused by rapid repeated stimulation that prevents complete relaxation.", "anatomy-166"],
  ["Muscular", "What is an isometric contraction?", "Muscle tension develops without a change in the muscle's overall length, as when holding a fixed object.", "anatomy-167"],
  ["Muscular", "What is an isotonic contraction?", "Muscle tension changes the length of the muscle, producing movement or controlled shortening/lengthening.", "anatomy-168"],
  ["Muscular", "Why does intense exercise increase lactate production?", "When oxygen delivery cannot meet ATP demand, glycolysis continues with pyruvate converted to lactate while NAD+ is regenerated.", "anatomy-169"],
  ["Muscular", "What is rigor mortis at the molecular level?", "Without ATP, myosin cannot detach normally from actin, so cross-bridges remain locked until proteins break down.", "anatomy-170"],
  ["Muscular", "What is muscle tone?", "A continuous, partial activation of resting skeletal muscles that supports posture and readiness.", "anatomy-171"],
  ["Nervous", "What are the functional classes of neurons?", "Sensory neurons carry input, interneurons process information, and motor neurons carry output to effectors.", "anatomy-172"],
  ["Nervous", "What is resting membrane potential?", "The voltage difference across a resting cell membrane, typically negative inside neurons because of ion gradients and selective permeability.", "anatomy-173"],
  ["Nervous", "What causes the rising phase of a neuronal action potential?", "Voltage-gated Na+ channels open, allowing Na+ influx and rapid depolarization.", "anatomy-174"],
  ["Nervous", "What causes repolarization after a neuronal action potential peak?", "Na+ channels inactivate and voltage-gated K+ channels allow K+ efflux, moving the membrane potential back toward negative values.", "anatomy-175"],
  ["Nervous", "What is the refractory period?", "The interval after an action potential when a neuron cannot or is less able to fire another action potential, limiting firing frequency and enforcing one-way propagation.", "anatomy-176"],
  ["Nervous", "What is saltatory conduction?", "Rapid action-potential propagation in myelinated axons from one node of Ranvier to the next.", "anatomy-177"],
  ["Nervous", "Which glial cell myelinates axons in the CNS and PNS?", "Oligodendrocytes myelinate CNS axons; Schwann cells myelinate PNS axons.", "anatomy-178"],
  ["Nervous", "What is an excitatory postsynaptic potential?", "A graded postsynaptic depolarization that makes the target cell more likely to reach threshold.", "anatomy-179"],
  ["Nervous", "What is an inhibitory postsynaptic potential?", "A graded change that makes the postsynaptic neuron less likely to fire, often by hyperpolarizing or stabilizing its membrane.", "anatomy-180"],
  ["Nervous", "What is temporal summation?", "Adding postsynaptic potentials that arrive repeatedly close together in time at one synapse.", "anatomy-181"],
  ["Nervous", "What is spatial summation?", "Adding simultaneous postsynaptic potentials arriving from multiple synapses or locations.", "anatomy-182"],
  ["Nervous", "What is the blood-brain barrier?", "A selective barrier formed largely by CNS capillary endothelial tight junctions and supporting cells that limits movement of substances into brain tissue.", "anatomy-183"],
  ["Nervous", "What is the difference between gray and white matter?", "Gray matter contains many neuronal cell bodies and synapses; white matter is rich in myelinated axons.", "anatomy-184"],
  ["Nervous", "What does the cerebellum contribute?", "Coordination, timing, balance, posture, and motor learning rather than initiating conscious motor commands alone.", "anatomy-185"],
  ["Nervous", "What is the medulla oblongata responsible for?", "It contains important autonomic centers regulating functions such as breathing, heart rate, blood pressure, swallowing, and vomiting.", "anatomy-186"],
  ["Nervous", "What is the sympathetic division's typical role?", "It prepares the body for activity or stress, increasing cardiac output and redirecting resources while reducing digestive activity.", "anatomy-187"],
  ["Nervous", "What is the parasympathetic division's typical role?", "It supports rest-and-digest functions, including digestion and energy conservation, while slowing the heart under appropriate conditions.", "anatomy-188"],
  ["Nervous", "What is a sensory receptor's transduction function?", "It converts a physical or chemical stimulus into a graded electrical signal in a sensory neuron or receptor cell.", "anatomy-189"],
  ["Nervous", "Why is the withdrawal reflex faster than a conscious response?", "Its spinal integration can activate motor neurons before the brain has fully processed the sensation, although the brain receives the signal afterward.", "anatomy-190"],
  ["Nervous", "What is long-term potentiation?", "A long-lasting increase in synaptic strength after appropriate activity, considered one cellular basis for learning and memory.", "anatomy-191"],
  ["Endocrine", "How does an endocrine hormone reach its target?", "It is released into interstitial fluid, enters the bloodstream, and acts on cells that possess the appropriate receptor.", "anatomy-192"],
  ["Endocrine", "What is the difference between peptide and steroid hormones?", "Peptide hormones are water-soluble and usually use membrane receptors; steroid hormones are lipid-soluble and often regulate intracellular receptors and gene expression.", "anatomy-193"],
  ["Endocrine", "What is the hypothalamus-pituitary relationship?", "The hypothalamus controls pituitary secretion through releasing hormones and neural signals, linking nervous and endocrine regulation.", "anatomy-194"],
  ["Endocrine", "What hormones are released by the posterior pituitary?", "Antidiuretic hormone and oxytocin, which are synthesized in the hypothalamus and transported to the posterior pituitary.", "anatomy-195"],
  ["Endocrine", "What are the main hormones of the anterior pituitary?", "Growth hormone, prolactin, ACTH, TSH, FSH, and LH; their secretion is regulated by hypothalamic signals and feedback.", "anatomy-196"],
  ["Endocrine", "What does thyroid hormone generally do?", "It increases basal metabolic activity and supports growth and development; secretion is regulated through the hypothalamus-pituitary-thyroid axis.", "anatomy-197"],
  ["Endocrine", "What does parathyroid hormone do when blood calcium falls?", "It raises blood calcium by increasing bone resorption, renal calcium reabsorption, and activation of vitamin D, which increases intestinal absorption.", "anatomy-198"],
  ["Endocrine", "What is insulin's effect on blood glucose?", "It lowers blood glucose by promoting cellular glucose uptake and storage as glycogen or other energy reserves.", "anatomy-199"],
  ["Endocrine", "What is glucagon's effect on blood glucose?", "It raises blood glucose by promoting hepatic glycogen breakdown and gluconeogenesis during low-glucose conditions.", "anatomy-200"],
  ["Endocrine", "Why is cortisol useful during stress but harmful when chronically elevated?", "It supports fuel availability and stress responses, but prolonged elevation can impair immunity, metabolism, bone, and tissue repair.", "anatomy-201"],
  ["Endocrine", "What is a tropic hormone?", "A hormone that targets another endocrine gland and stimulates its hormone secretion, such as TSH acting on the thyroid.", "anatomy-202"],
  ["Endocrine", "What is permissiveness in endocrine physiology?", "One hormone enables another hormone's full effect, often by increasing receptor expression or providing a required cellular condition.", "anatomy-203"],
  ["Endocrine", "What is up-regulation of a receptor?", "An increase in receptor number or sensitivity, often when a hormone or signal is chronically low.", "anatomy-204"],
  ["Endocrine", "A patient has high thyroid hormone and low TSH. What feedback pattern does this suggest?", "Negative feedback: elevated thyroid hormone suppresses hypothalamic and anterior-pituitary stimulation.", "anatomy-205"],
  ["Endocrine", "What is the difference between diabetes mellitus type 1 and type 2?", "Type 1 involves autoimmune loss of insulin-producing beta cells; type 2 begins primarily with insulin resistance and can progress to beta-cell dysfunction.", "anatomy-206"],
  ["Cardiovascular", "What is the sequence of electrical conduction through the heart?", "SA node, atrial pathways, AV node, AV bundle, right and left bundle branches, and Purkinje fibers.", "anatomy-207"],
  ["Cardiovascular", "Why is there an AV-node delay?", "It allows the atria time to complete ventricular filling before ventricular contraction.", "anatomy-208"],
  ["Cardiovascular", "What is the Frank-Starling mechanism?", "Within physiological limits, increased ventricular filling stretches cardiac muscle and produces a stronger contraction and larger stroke volume.", "anatomy-209"],
  ["Cardiovascular", "What determines mean arterial pressure approximately?", "A useful approximation is diastolic pressure plus one-third of pulse pressure, or cardiac output times total peripheral resistance.", "anatomy-210"],
  ["Cardiovascular", "What is pulse pressure?", "Systolic pressure minus diastolic pressure.", "anatomy-211"],
  ["Cardiovascular", "A blood pressure is 120/80 mmHg. What is its approximate mean arterial pressure?", "Pulse pressure is 40 mmHg; MAP is approximately 80 + 40/3 = 93 mmHg.", "anatomy-212"],
  ["Cardiovascular", "How do arteries differ from veins?", "Arteries carry blood away from the heart under higher pressure with thicker walls; veins return blood at lower pressure and often contain valves.", "anatomy-213"],
  ["Cardiovascular", "Why are capillaries effective exchange vessels?", "Their walls are usually one endothelial cell thick, slowing flow and minimizing diffusion distance.", "anatomy-214"],
  ["Cardiovascular", "What is vasoconstriction?", "Contraction of vascular smooth muscle that decreases vessel radius and generally increases resistance and blood pressure.", "anatomy-215"],
  ["Cardiovascular", "What is the lymphatic system's cardiovascular connection?", "It returns excess interstitial fluid and proteins to the bloodstream and supports immune surveillance and lipid absorption.", "anatomy-216"],
  ["Cardiovascular", "What are the major plasma proteins?", "Albumin, globulins, and fibrinogen; they help maintain osmotic pressure, transport substances, support immunity, and clot blood.", "anatomy-217"],
  ["Cardiovascular", "What is hemostasis?", "The coordinated process of vascular constriction, platelet plug formation, and coagulation that limits bleeding.", "anatomy-218"],
  ["Cardiovascular", "Why can a clot be dangerous if it travels?", "An embolus can obstruct blood flow in a smaller vessel, depriving downstream tissue of oxygen.", "anatomy-219"],
  ["Cardiovascular", "What is the difference between pulmonary and systemic circulation?", "Pulmonary circulation carries blood between heart and lungs; systemic circulation carries blood between heart and body tissues.", "anatomy-220"],
  ["Cardiovascular", "How does anemia affect oxygen delivery?", "Reduced hemoglobin or red-cell mass lowers blood oxygen content, so tissues may receive less oxygen even if lung diffusion is normal.", "anatomy-221"],
  ["Respiratory", "What is the difference between ventilation and respiration?", "Ventilation moves air; external respiration exchanges gases between alveoli and blood; internal respiration exchanges gases between blood and tissues.", "anatomy-222"],
  ["Respiratory", "What is dead space?", "Air in conducting passages that does not participate directly in alveolar gas exchange.", "anatomy-223"],
  ["Respiratory", "What is vital capacity?", "The maximum volume exhaled after a maximum inhalation: inspiratory reserve volume plus tidal volume plus expiratory reserve volume.", "anatomy-224"],
  ["Respiratory", "How does surfactant prevent alveolar collapse?", "It lowers surface tension at the air-liquid interface, reducing the pressure needed to keep small alveoli open.", "anatomy-225"],
  ["Respiratory", "What happens to hemoglobin's oxygen affinity when carbon dioxide and acidity rise?", "Affinity decreases, promoting oxygen unloading to metabolically active tissues; this is part of the Bohr effect.", "anatomy-226"],
  ["Respiratory", "How is most carbon dioxide converted for transport?", "Carbonic anhydrase in red blood cells catalyzes conversion to carbonic acid, which dissociates into H+ and bicarbonate.", "anatomy-227"],
  ["Digestive", "What begins carbohydrate digestion in the mouth?", "Salivary amylase begins hydrolyzing starch into smaller carbohydrates.", "anatomy-228"],
  ["Digestive", "What is the role of secretin?", "Acidic chyme stimulates secretin, which promotes pancreatic bicarbonate secretion and helps reduce duodenal acidity.", "anatomy-229"],
  ["Digestive", "What is the role of cholecystokinin?", "Fat and amino acids stimulate CCK, which promotes pancreatic enzyme secretion and gallbladder contraction and slows gastric emptying.", "anatomy-230"],
  ["Digestive", "How are long-chain dietary lipids transported after absorption?", "They are packaged into chylomicrons, enter lymphatic lacteals, and then reach the bloodstream.", "anatomy-231"],
  ["Digestive", "Why does the small intestine have plicae, villi, and microvilli?", "These structures greatly increase absorptive surface area and slow or mix intestinal contents for efficient exchange.", "anatomy-232"],
  ["Excretory", "What is glomerular filtration rate conceptually?", "The volume of filtrate formed by all renal glomeruli per unit time; it reflects kidney filtration function.", "anatomy-233"],
  ["Excretory", "Why are large proteins usually absent from normal filtrate?", "The filtration barrier restricts passage by size and charge, retaining most plasma proteins in the blood.", "anatomy-234"],
  ["Excretory", "What is the role of the proximal convoluted tubule?", "It reabsorbs much of the filtered water, sodium, bicarbonate, glucose, amino acids, and other valuable solutes.", "anatomy-235"],
  ["Excretory", "What is countercurrent multiplication in the nephron?", "Opposing flows and selective permeability in the loop of Henle build a medullary osmotic gradient that enables concentrated urine.", "anatomy-236"],
  ["Excretory", "How does aldosterone affect the nephron?", "It increases sodium reabsorption and potassium secretion in the distal nephron; water follows sodium when permeability permits.", "anatomy-237"],
  ["Immune", "What is the difference between MHC class I and class II presentation?", "MHC I displays intracellular peptides to CD8 cytotoxic T cells; MHC II displays extracellular-derived peptides to CD4 helper T cells.", "anatomy-238"],
  ["Immune", "What do helper T cells do?", "They coordinate adaptive responses through cytokines, activating or supporting B cells, cytotoxic T cells, and other immune cells.", "anatomy-239"],
  ["Reproductive", "What is spermatogenesis versus oogenesis?", "Spermatogenesis continuously produces four functional sperm from each meiotic precursor; oogenesis produces one large ovum and polar bodies with unequal divisions.", "anatomy-240"],
  ["Reproductive", "What is fertilization's genetic significance?", "It restores diploidy by combining haploid gametes and creates a new allele combination through random gamete union.", "anatomy-241"],
  ["Reproductive", "Why are secondary sexual characteristics not the same as gamete production?", "They are body changes influenced by sex hormones, whereas gamete production is the formation of sperm or ova in reproductive organs.", "anatomy-242"],
  ["General", "What is the difference between a set point and a normal range?", "A set point is a target value used by a regulatory system; a normal range is the span of values compatible with healthy function around that target.", "anatomy-243"],
  ["General", "Why is homeostasis dynamic rather than perfectly constant?", "Regulated variables fluctuate around a range as sensors, control centers, effectors, metabolism, and the environment continually change.", "anatomy-244"],
  ["General", "A cut is made parallel to the body's midline. Which plane is the section?", "A sagittal section; if it divides the body into equal left and right halves, it is specifically midsagittal.", "anatomy-245"],
  ["General", "What is the difference between a serous membrane and a mucous membrane?", "A serous membrane lines closed ventral body cavities and reduces organ friction; a mucous membrane lines passages open to the exterior and secretes mucus.", "anatomy-246"],
  ["Cells", "A cell is placed in a hypertonic solution. What happens to its water balance?", "Water leaves the cell by osmosis toward the solution with greater effective solute concentration, so the cell shrinks unless it compensates.", "anatomy-247"],
  ["Cells", "Why can a red blood cell burst in a hypotonic solution?", "Water enters by osmosis, and the cell lacks a rigid wall to resist swelling, so its membrane can rupture.", "anatomy-248"],
  ["Cells", "How can a membrane carrier move solute without ATP?", "Passive movement down an electrochemical gradient through a membrane channel or carrier, without direct ATP use.", "anatomy-249"],
  ["Cells", "What is endocytosis?", "An active process in which the plasma membrane encloses extracellular material in a vesicle for uptake.", "anatomy-250"],
  ["Cells", "How does the sodium-potassium pump support cell function?", "Using ATP, it moves three Na+ out and two K+ in per cycle, maintaining ion gradients that support membrane potential and transport.", "anatomy-251"],
  ["Cells", "What is the cell cycle checkpoint purpose?", "Checkpoints assess DNA integrity, replication, and chromosome attachment before the cell commits to the next stage of division.", "anatomy-252"],
  ["Respiratory", "What is the difference between external and internal respiration?", "External respiration exchanges gases between alveoli and pulmonary blood; internal respiration exchanges gases between systemic blood and tissues.", "anatomy-253"],
  ["Respiratory", "During quiet inspiration, what happens to thoracic pressure?", "Diaphragm contraction increases thoracic volume, lowering intrapulmonary pressure below atmospheric pressure so air flows inward.", "anatomy-254"],
  ["Respiratory", "Why does expiration occur at rest without active abdominal contraction?", "The inspiratory muscles relax and elastic recoil reduces thoracic volume, raising alveolar pressure above atmospheric pressure.", "anatomy-255"],
  ["Respiratory", "What is respiratory minute volume?", "The total air moved per minute: respiratory rate multiplied by tidal volume.", "anatomy-256"],
  ["Respiratory", "A person breathes 12 times per minute with a tidal volume of 0.5 L. What is minute ventilation?", "12 x 0.5 L = 6.0 L per minute.", "anatomy-257"],
  ["Respiratory", "How does emphysema impair gas exchange?", "Destruction of alveolar walls reduces surface area and elastic recoil, lowering effective diffusion and making expiration difficult.", "anatomy-258"],
  ["Respiratory", "Why does carbon monoxide poisoning reduce oxygen delivery?", "Carbon monoxide binds hemoglobin strongly, reducing oxygen-carrying sites and impairing release of oxygen that remains bound.", "anatomy-259"],
  ["Respiratory", "What is the medulla's role in breathing control?", "Medullary respiratory centers generate and adjust the basic rhythm using input about carbon dioxide, pH, and other signals.", "anatomy-260"],
  ["Digestive", "What is the role of the lower esophageal sphincter?", "It helps prevent acidic stomach contents from refluxing into the esophagus after swallowed material passes.", "anatomy-261"],
  ["Digestive", "Why does the small intestine receive pancreatic bicarbonate?", "Bicarbonate neutralizes acidic chyme from the stomach and creates a pH suitable for pancreatic and intestinal enzymes.", "anatomy-262"],
  ["Digestive", "What is the difference between absorption and assimilation?", "Absorption moves digested substances into blood or lymph; assimilation is their use or incorporation by body cells.", "anatomy-263"],
  ["Digestive", "How are water-soluble nutrients transported after intestinal absorption?", "Many enter blood capillaries in villi and travel through the hepatic portal vein to the liver before the general circulation.", "anatomy-264"],
  ["Digestive", "What is the hepatic portal system's advantage?", "It delivers absorbed nutrients and some toxins first to the liver for processing, storage, detoxification, or modification.", "anatomy-265"],
  ["Digestive", "Why does lactase deficiency cause bloating after dairy intake?", "Undigested lactose remains in the intestinal lumen, where it draws water osmotically and is fermented by bacteria to gas and acids.", "anatomy-266"],
  ["Digestive", "What is the role of pepsin?", "It is an active stomach protease that begins protein digestion in the acidic environment created by gastric secretions.", "anatomy-267"],
  ["Immune", "What is the difference between an antigen and an antibody?", "An antigen is a recognized target molecule; an antibody is a specific immunoglobulin produced by plasma cells that binds the target.", "anatomy-268"],
  ["Immune", "Why do memory cells improve a secondary immune response?", "They persist after the first response and can rapidly generate more effective effector cells and antibodies after re-exposure.", "anatomy-269"],
  ["Immune", "What is clonal selection?", "An antigen activates the lymphocyte with a matching receptor, causing that cell to proliferate and produce effector and memory descendants.", "anatomy-270"],
  ["Immune", "How do antibodies neutralize a pathogen?", "They bind toxins or attachment sites and block interaction with host cells; they can also promote opsonization or complement activation.", "anatomy-271"],
  ["Immune", "Why can an autoimmune disease occur?", "Self-reactive immune cells escape or overcome tolerance and attack the body's own antigens, often with genetic and environmental contributions.", "anatomy-272"],
  ["Immune", "What is an allergic hypersensitivity response?", "An exaggerated immune response to a normally harmless antigen that can cause inflammation and tissue symptoms.", "anatomy-273"],
  ["Immune", "What is the difference between lymph and plasma?", "Lymph is interstitial fluid collected by lymphatic vessels; plasma is the liquid component of blood containing proteins and dissolved substances.", "anatomy-274"],
  ["Cardiovascular", "What is the path of oxygenated blood from the lungs to the aorta?", "Pulmonary veins, left atrium, mitral valve, left ventricle, aortic valve, and aorta.", "anatomy-275"],
  ["Cardiovascular", "What is the cardiac conduction sequence?", "SA node, atrial pathways and AV node, AV bundle, bundle branches, and Purkinje fibers.", "anatomy-276"],
  ["Cardiovascular", "Why is the AV node delay useful?", "It allows the atria to finish emptying into the ventricles before ventricular depolarization and contraction.", "anatomy-277"],
  ["Cardiovascular", "A ventricle ejects 70 mL per beat at 75 beats per minute. What is cardiac output?", "70 mL/beat x 75 beats/min = 5,250 mL/min, or 5.25 L/min.", "anatomy-278"],
  ["Cardiovascular", "What is the difference between arteries and veins?", "Arteries carry blood away from the heart under generally higher pressure; veins return blood and use valves and skeletal-muscle pumps to aid flow.", "anatomy-279"],
  ["Cardiovascular", "Why do capillaries have very thin walls?", "A single endothelial layer shortens the diffusion distance for gases, nutrients, wastes, and fluid between blood and tissues.", "anatomy-280"],
  ["Cardiovascular", "How does vasoconstriction affect blood pressure?", "It increases vascular resistance and can raise arterial pressure when other factors are held similar.", "anatomy-281"],
  ["Cardiovascular", "What is the role of the lymphatic system in fluid balance?", "It returns excess interstitial fluid and leaked proteins to the bloodstream and helps prevent tissue swelling.", "anatomy-282"],
  ["Nervous", "What is the resting membrane potential?", "The voltage difference across a cell membrane when a neuron is not actively conducting an action potential, created by ion gradients and selective permeability.", "anatomy-283"],
  ["Nervous", "What is depolarization?", "A shift in membrane potential toward a less negative or more positive value, commonly caused by sodium entry during an action potential.", "anatomy-284"],
  ["Nervous", "Why is an action potential described as all-or-none?", "Once threshold is reached, a neuron produces a full-size action potential; stronger stimuli increase frequency rather than amplitude.", "anatomy-285"],
  ["Nervous", "What makes conduction jump between nodes?", "Rapid action-potential propagation in a myelinated axon from one node of Ranvier to the next.", "anatomy-286"],
  ["Nervous", "How do neurotransmitters affect a postsynaptic cell?", "They bind receptors that alter ion flow or signaling pathways, producing excitatory, inhibitory, or modulatory effects.", "anatomy-287"],
  ["Nervous", "How does a reflex pathway produce a rapid response?", "A rapid pathway from sensory receptor through afferent neurons and an integration center to an efferent neuron and effector.", "anatomy-288"],
  ["Nervous", "What is the difference between sympathetic and parasympathetic activity?", "Sympathetic activity generally supports mobilization during stress; parasympathetic activity supports rest, digestion, and energy conservation.", "anatomy-289"],
  ["Nervous", "Why can a spinal cord injury cause deficits below the injury?", "Ascending sensory and descending motor pathways pass through the cord, so damage can interrupt signals between the brain and lower regions.", "anatomy-290"],
  ["Excretory", "What is the nephron's basic sequence?", "Filtration at the renal corpuscle, tubular reabsorption and secretion, and excretion of the resulting urine.", "anatomy-291"],
  ["Excretory", "How does ADH change urine concentration?", "ADH increases collecting-duct water permeability, allowing more water reabsorption into the concentrated medulla and producing smaller-volume urine.", "anatomy-292"],
  ["Excretory", "Why does glucose normally not appear in urine?", "Filtered glucose is normally reabsorbed in the proximal tubule; glucose appears when filtered load exceeds transport capacity or reabsorption is impaired.", "anatomy-293"],
  ["Excretory", "What is renal clearance conceptually?", "The virtual volume of plasma from which a substance is completely removed per unit time, used to assess filtration or handling.", "anatomy-294"],
  ["Excretory", "How do the kidneys help regulate blood pH?", "They excrete hydrogen ions, reabsorb filtered bicarbonate, and generate new bicarbonate to buffer acids.", "anatomy-295"],
  ["Endocrine", "What is the difference between endocrine and exocrine secretion?", "Endocrine glands release hormones into interstitial fluid and blood; exocrine glands release products through ducts to surfaces or cavities.", "anatomy-296"],
  ["Endocrine", "What is a target cell?", "A cell with receptors for a hormone or signal, allowing it to respond even when other cells are exposed to the same molecule.", "anatomy-297"],
  ["Endocrine", "Why do steroid hormones often act through intracellular receptors?", "They are lipid-soluble enough to cross the plasma membrane and alter gene transcription through receptor complexes.", "anatomy-298"],
  ["Endocrine", "How does insulin lower blood glucose?", "It promotes glucose uptake in responsive tissues and supports storage as glycogen and other fuels while reducing hepatic glucose output.", "anatomy-299"],
  ["Endocrine", "How does glucagon raise blood glucose?", "It stimulates hepatic glycogen breakdown and glucose production during low blood glucose.", "anatomy-300"],
  ["Endocrine", "Which hormones act on endocrine glands to control their secretion?", "A hormone that acts on another endocrine gland to stimulate its secretion or growth, such as TSH acting on the thyroid.", "anatomy-301"],
  ["Integumentary", "What is the epidermis's main protective role?", "Its keratinized stratified epithelium forms a barrier against abrasion, water loss, and entry of many pathogens.", "anatomy-302"],
  ["Integumentary", "What physical process removes heat when sweat dries?", "Evaporation of sweat removes heat from the skin surface, provided surrounding conditions allow evaporation.", "anatomy-303"],
  ["Muscular", "What is the sliding-filament explanation for muscle contraction?", "Myosin heads pull actin filaments toward the sarcomere center, shortening the sarcomere without shortening the thick or thin filaments themselves.", "anatomy-304"],
  ["Muscular", "What triggers skeletal-muscle contraction at the neuromuscular junction?", "A motor neuron releases acetylcholine, which depolarizes the muscle fiber and leads to calcium release from the sarcoplasmic reticulum.", "anatomy-305"],
  ["Muscular", "Why does ATP remain necessary after a cross-bridge forms?", "ATP binding helps detach myosin from actin, and ATP hydrolysis re-cocks the myosin head for another cycle.", "anatomy-306"],
  ["Skeletal", "What is the difference between an osteoblast and an osteoclast?", "Osteoblasts build bone matrix; osteoclasts resorb bone and help release stored minerals.", "anatomy-307"],
  ["Skeletal", "Why is calcium homeostasis important for both bone and nerves?", "Calcium supports mineralized bone and is also required for neurotransmitter release, muscle contraction, and intracellular signaling.", "anatomy-308"],
  ["Reproductive", "What is the role of FSH and LH in the reproductive system?", "They regulate gonadal function: FSH supports gamete-related processes and LH stimulates ovulation or testosterone production depending on the gonad.", "anatomy-309"],
  ["Reproductive", "Where does fertilization most commonly occur?", "In the ampulla of the uterine tube, before the early embryo travels toward the uterus.", "anatomy-310"],
  ["Forum Marathon", "A patient's heart rate rises but stroke volume falls. What happens to cardiac output if the changes exactly offset?", "Cardiac output can remain unchanged because it equals heart rate multiplied by stroke volume; the actual result requires the numerical values.", "anatomy-311"],
  ["Forum Marathon", "A person hyperventilates for several minutes. What immediate blood-gas change is expected?", "Carbon dioxide falls, reducing carbonic acid and raising blood pH, producing respiratory alkalosis if sustained.", "anatomy-312"],
  ["Forum Marathon", "Why can severe diarrhea cause both dehydration and acidosis?", "Loss of intestinal fluid removes water and electrolytes, and loss of bicarbonate-rich fluid can lower blood buffering capacity.", "anatomy-313"],
  ["Forum Marathon", "A patient has low plasma albumin and swollen ankles. What mechanism is likely?", "Reduced plasma oncotic pressure favors filtration of fluid into tissues, contributing to edema.", "anatomy-314"],
  ["Forum Marathon", "A drug blocks voltage-gated sodium channels in an axon. What process is impaired first?", "Action-potential depolarization and propagation are impaired because rapid sodium entry is unavailable.", "anatomy-315"],
  ["Forum Marathon", "A spirometry result shows reduced forced expiratory volume with a relatively preserved vital capacity. What broad problem should be considered?", "An obstructive pattern with difficulty moving air out, while confirming interpretation with the full set of measured ratios and clinical context.", "anatomy-316"],
  ["Forum Marathon", "A patient has high blood glucose and glucose in urine. What renal explanation fits?", "Filtered glucose exceeds proximal-tubule transport capacity, so the excess remains in tubular fluid and is excreted.", "anatomy-317"],
  ["Forum Marathon", "Why can fever increase metabolic demand?", "Higher temperature can accelerate biochemical reactions and increase oxygen and energy requirements, while cytokines alter the hypothalamic set point.", "anatomy-318"],
  ["Forum Marathon", "A person loses a large amount of blood. Which homeostatic responses help maintain pressure first?", "Sympathetic activation raises heart rate and contractility and constricts vessels; longer-term responses conserve fluid through hormones such as ADH and aldosterone.", "anatomy-319"],
  ["Forum Marathon", "How should an anatomy mechanism answer distinguish cause from symptom?", "Name the initiating structural or physiological change, trace the immediate effect, then connect it to the observed symptom without treating the symptom as the cause.", "anatomy-320"],
  ["Forum Marathon", "A student identifies a structure only by location. What second evidence improves the identification?", "Use distinctive relationships, tissue appearance, function, blood supply or innervation, and neighboring structures rather than location alone.", "anatomy-321"],
  ["Forum Marathon", "What is a reliable workflow for an unfamiliar A&P diagram?", "Orient the body and plane, identify landmarks, trace connected structures, infer function from tissue and flow direction, and check the conclusion against homeostasis.", "anatomy-322"],
  ["Respiratory", "A climber rapidly ascends to high altitude and begins breathing faster. What stimulus drives this response?", "Lower arterial oxygen stimulates peripheral chemoreceptors, increasing ventilation to improve oxygen uptake.", "anatomy-323"],
  ["Respiratory", "A patient's alveoli fill with fluid during pulmonary edema. Why does blood oxygen fall?", "Fluid increases diffusion distance and reduces effective gas-exchange area, slowing oxygen movement into pulmonary capillaries.", "anatomy-324"],
  ["Respiratory", "A premature infant lacks adequate surfactant. What happens to the alveoli?", "Surface tension rises, making alveoli harder to inflate and more likely to collapse during expiration.", "anatomy-325"],
  ["Respiratory", "A foreign object blocks the right main bronchus. Which immediate ventilation problem results?", "Airflow to much of the right lung falls, creating poorly ventilated regions despite continued perfusion.", "anatomy-326"],
  ["Digestive", "A gallstone blocks the common bile duct after a fatty meal. Which digestive process is most impaired?", "Fat emulsification and absorption are impaired because bile cannot effectively reach the duodenum.", "anatomy-327"],
  ["Digestive", "A patient loses the terminal ileum. Which nutrient deficiency is especially likely over time?", "Vitamin B12 deficiency is likely because the vitamin-intrinsic-factor complex is normally absorbed in the terminal ileum.", "anatomy-328"],
  ["Digestive", "Pancreatic bicarbonate secretion is greatly reduced. How is small-intestinal digestion affected?", "Acidic chyme is not adequately neutralized, so duodenal tissue is stressed and pancreatic enzymes work less effectively.", "anatomy-329"],
  ["Digestive", "A patient has damaged intestinal villi. Why can weight loss occur despite adequate food intake?", "Reduced absorptive surface prevents efficient nutrient uptake, producing malabsorption even when digestion and intake continue.", "anatomy-330"],
  ["Immune", "A child has normal T-cell counts but cannot produce antibodies. Which adaptive function is directly impaired?", "B-cell or plasma-cell humoral immunity is impaired, reducing antibody-mediated neutralization and opsonization.", "anatomy-331"],
  ["Immune", "A vaccinated person responds rapidly after later exposure to the same pathogen. What explains the faster response?", "Memory B and T cells formed during the primary response expand quickly and produce a stronger secondary response.", "anatomy-332"],
  ["Immune", "A patient taking an antihistamine has less redness and swelling after an allergen exposure. What changed?", "Blocking histamine reduces vasodilation and capillary permeability, limiting local inflammatory signs.", "anatomy-333"],
  ["Immune", "A splinter introduces bacteria through the skin. Put the early defenses in functional order.", "The breached barrier is followed by local inflammation, complement and phagocyte recruitment, then adaptive responses if innate control is insufficient.", "anatomy-334"],
  ["Cardiovascular", "A heart rate of 120 beats/min accompanies a stroke volume of 50 mL. What is cardiac output?", "120 x 50 = 6,000 mL/min, or 6.0 L/min.", "anatomy-335"],
  ["Cardiovascular", "The mitral valve does not close completely. Where does blood move during left ventricular contraction?", "Some blood regurgitates into the left atrium instead of all moving through the aorta.", "anatomy-336"],
  ["Cardiovascular", "A coronary artery is suddenly blocked. Why can ventricular contraction weaken?", "Downstream myocardium loses oxygen and ATP production, impairing ion handling and actin-myosin contraction.", "anatomy-337"],
  ["Cardiovascular", "A person stands suddenly and briefly becomes dizzy. Which reflex normally restores pressure?", "The baroreceptor reflex raises sympathetic output, increasing heart rate, contractility, and vasoconstriction.", "anatomy-338"],
  ["Cardiovascular", "A deep-vein clot reaches the pulmonary circulation. What happens to gas exchange?", "Perfusion is blocked to ventilated alveoli, increasing physiologic dead space and reducing effective oxygenation.", "anatomy-339"],
  ["Nervous", "A lesion damages the dorsal root of a spinal nerve but spares the ventral root. What deficit is expected?", "Sensory input from that region is impaired while motor output through the spared ventral root can remain intact.", "anatomy-340"],
  ["Nervous", "A demyelinating disorder slows neural signaling. Why?", "Current leaks across exposed membrane and saltatory conduction between nodes is disrupted, delaying or blocking action potentials.", "anatomy-341"],
  ["Nervous", "A patient can understand speech but cannot produce fluent words. Which functional region is likely affected?", "The dominant frontal language-production region, commonly called Broca's area, is likely affected.", "anatomy-342"],
  ["Nervous", "Touching a hot pan causes withdrawal before pain is consciously perceived. Why?", "A spinal reflex circuit activates flexor muscles before ascending sensory signals finish reaching conscious brain centers.", "anatomy-343"],
  ["Excretory", "A dehydrated person produces a small volume of concentrated urine. Which hormone is central to this response?", "ADH increases collecting-duct water permeability, returning more water to blood.", "anatomy-344"],
  ["Excretory", "A substance is filtered and completely reabsorbed but not secreted. How much appears in urine?", "None under those assumptions; its excretion equals filtration minus reabsorption, which is zero.", "anatomy-345"],
  ["Excretory", "Blood pressure drops severely. How does activation of the renin-angiotensin-aldosterone system help?", "Angiotensin II promotes vasoconstriction and aldosterone promotes sodium retention, supporting blood volume and pressure.", "anatomy-346"],
  ["Excretory", "A ureter is obstructed by a stone. Why can filtration in that kidney decrease?", "Pressure backs up toward the renal pelvis and nephron, opposing glomerular filtration pressure.", "anatomy-347"],
  ["Endocrine", "A thyroid hormone level is high while TSH is low. What feedback pattern does this suggest?", "High thyroid hormone is suppressing pituitary TSH through negative feedback; the source may be thyroid autonomy or excess hormone.", "anatomy-348"],
  ["Endocrine", "Insulin is present, but target cells respond poorly. What happens to blood glucose?", "Glucose uptake and storage fall, so blood glucose remains elevated despite insulin presence.", "anatomy-349"],
  ["Endocrine", "A patient cannot produce cortisol during prolonged stress. Which metabolic support is reduced?", "The ability to maintain blood glucose and mobilize fuels during sustained stress is reduced.", "anatomy-350"],
  ["Muscular", "A toxin prevents acetylcholine release at the neuromuscular junction. What happens to skeletal muscle?", "End-plate depolarization fails, so action potentials and voluntary contraction are weakened or absent.", "anatomy-351"],
  ["Muscular", "A muscle runs out of ATP immediately after death. Why does stiffness develop?", "Myosin heads cannot detach efficiently from actin, producing rigor until proteins degrade.", "anatomy-352"],
  ["Muscular", "During an isometric contraction, force rises but a joint does not move. What remains constant?", "Muscle length and joint angle remain essentially constant while tension increases.", "anatomy-353"],
  ["Skeletal", "An older adult is immobilized for months. Why can bone mass decrease?", "Reduced mechanical loading shifts remodeling toward resorption, weakening bone over time.", "anatomy-354"],
  ["Skeletal", "A fracture damages the epiphyseal plate in a child. What long-term problem may result?", "Longitudinal growth of that bone may become slowed, asymmetric, or prematurely stopped.", "anatomy-355"],
  ["Integumentary", "A full-thickness burn destroys sweat glands and dermal vessels. Which homeostatic functions are threatened?", "Temperature regulation, fluid retention, barrier defense, sensation, and wound healing are all impaired.", "anatomy-356"],
  ["Integumentary", "A mole becomes asymmetric with irregular borders and changing color. What action is appropriate?", "Prompt professional evaluation is warranted because these are warning signs used to screen for melanoma.", "anatomy-357"],
  ["Reproductive", "The uterine tubes are blocked but ovarian function is normal. Which process is directly prevented?", "Sperm and oocyte cannot normally meet in the tube, preventing natural fertilization despite continued ovulation.", "anatomy-358"],
  ["General", "A patient sweats as body temperature rises above its set point. Identify the feedback components.", "Thermoreceptors are sensors, the hypothalamus is the control center, and sweat glands and skin vessels are effectors in negative feedback.", "anatomy-359"],
  ["Cells", "A red blood cell is placed in a strongly hypotonic solution. What happens and why?", "Water enters by osmosis, causing the cell to swell and potentially lyse.", "anatomy-360"],
  ["Cells", "A drug stops mitochondrial ATP production. Which membrane process fails early?", "Energy-dependent active transport, including ion pumps such as the sodium-potassium pump, is quickly impaired.", "anatomy-361"],
  ["Forum Marathon", "A patient has rapid breathing, low blood pressure, cool skin, and confusion after major bleeding. Connect these findings.", "Blood loss lowers circulating volume and tissue perfusion; sympathetic compensation causes tachypnea and skin vasoconstriction, while reduced brain perfusion causes confusion.", "anatomy-362"],
  ["Respiratory", "A person breathes 14 times per minute with a tidal volume of 500 mL. What is their minute ventilation?", "14 x 500 = 7,000 mL/min, or 7.0 L/min.", "anatomy-363"],
  ["Respiratory", "Pneumonia fills alveoli in one lung lobe with exudate. How do local ventilation, perfusion, and vessel tone change in that region?", "Ventilation to the fluid-filled alveoli drops while perfusion initially continues, lowering the local V/Q ratio; hypoxic pulmonary vasoconstriction then narrows local vessels to redirect blood toward better-ventilated regions.", "anatomy-364"],
  ["Respiratory", "A chest wall injury allows air into the pleural space, raising intrapleural pressure toward atmospheric. What happens to that lung and why?", "The lung collapses because the negative intrapleural pressure that normally holds it expanded against its own elastic recoil is lost.", "anatomy-365"],
  ["Digestive", "Chronic pancreatitis greatly reduces lipase secretion. Which nutrient class is digested least efficiently, and what stool change often results?", "Fat digestion is impaired most, producing steatorrhea: bulky, pale, greasy, foul-smelling stools from undigested fat.", "anatomy-366"],
  ["Digestive", "A vagotomy reduces parasympathetic input to the stomach. What happens to gastric secretion and motility?", "Both gastric acid/enzyme secretion and motility decrease, since vagal (parasympathetic) stimulation normally promotes digestive gland activity and smooth muscle contraction.", "anatomy-367"],
  ["Digestive", "A segment of small intestine becomes obstructed and distends with trapped fluid and gas. Why can this cause dehydration and electrolyte imbalance?", "Fluid accumulates in the lumen instead of being absorbed, and associated vomiting can cause further loss of water, hydrogen ions, and electrolytes, risking dehydration and acid-base disturbance.", "anatomy-368"],
  ["Immune", "A patient on chronic high-dose corticosteroids develops frequent infections. Why?", "Corticosteroids broadly suppress inflammatory signaling and immune cell activity, reducing the body's ability to detect and clear pathogens.", "anatomy-369"],
  ["Immune", "A patient has a genetic deficiency of complement protein C3. Which innate immune functions are most impaired?", "Opsonization, the membrane attack complex, and inflammatory cell recruitment are all impaired, since C3 is central to all three major complement pathways.", "anatomy-370"],
  ["Immune", "Within minutes of a bee sting, a patient develops hives, facial swelling, and difficulty breathing. Which hypersensitivity type and cell/mediator explain this?", "Type I (immediate) hypersensitivity; mast cells release histamine and other mediators that cause vasodilation, increased vascular permeability, and bronchoconstriction.", "anatomy-371"],
  ["Cardiovascular", "A patient's blood pressure is 120/80 mmHg. Calculate the pulse pressure and an approximate mean arterial pressure.", "Pulse pressure = 120 - 80 = 40 mmHg; MAP is about 80 + (1/3 x 40) = 93 mmHg.", "anatomy-372"],
  ["Cardiovascular", "An ECG shows a regular but slow rhythm with no P wave before each QRS complex. Which part of the conduction system is likely pacing the heart instead of the SA node?", "The AV node, producing a junctional rhythm, since the atria are not generating or conducting a normal SA-node signal.", "anatomy-373"],
  ["Cardiovascular", "A patient has severe chronic anemia. How does the heart typically compensate to maintain oxygen delivery to tissues?", "Heart rate and cardiac output rise to compensate for the blood's reduced oxygen-carrying capacity per unit volume.", "anatomy-374"],
  ["Nervous", "A stroke damages the primary motor cortex in the left hemisphere. Which side of the body is most affected, and why?", "The right side of the body, because descending motor tracts cross (decussate) before reaching the spinal cord.", "anatomy-375"],
  ["Nervous", "A patient develops cerebellar damage. What type of movement problem is expected even though muscle strength is normal?", "Impaired coordination, balance, and smooth execution of voluntary movements (ataxia), since the cerebellum fine-tunes movement rather than generating raw strength.", "anatomy-376"],
  ["Nervous", "A sudden stressful event triggers a sympathetic surge. What happens to heart rate, pupils, and digestive activity?", "Heart rate increases, pupils dilate, and digestive activity decreases as the body redirects resources toward immediate physical response.", "anatomy-377"],
  ["Excretory", "A patient's glomerular filtration rate drops suddenly, but blood creatinine has not yet been measured. Why does blood creatinine take time to rise after a drop in GFR?", "Creatinine accumulates gradually as filtration lags behind production, so blood levels take time to reach a new, higher steady state after GFR falls.", "anatomy-378"],
  ["Excretory", "A diuretic blocks sodium reabsorption in the loop of Henle. What happens to urine volume and concentration?", "Urine volume increases and becomes less concentrated, because less sodium (and the water that follows it) is reabsorbed and the medullary concentration gradient is weakened.", "anatomy-379"],
  ["Excretory", "A patient develops a metabolic acidosis. How do the kidneys help restore blood pH over hours to days?", "The kidneys increase hydrogen ion excretion and generate/reabsorb more bicarbonate, gradually raising blood pH toward normal.", "anatomy-380"],
  ["Excretory", "A substance is filtered at 125 mL/min with a plasma concentration of 2 mg/mL, and it is neither reabsorbed nor secreted. What is its excretion rate?", "125 mL/min x 2 mg/mL = 250 mg/min.", "anatomy-381"],
  ["Endocrine", "A tumor secretes aldosterone independent of normal regulation. What electrolyte and blood pressure changes are expected?", "Sodium retention and potassium loss increase, raising blood pressure; renin is typically suppressed by the resulting volume expansion.", "anatomy-382"],
  ["Endocrine", "The posterior pituitary fails to release adequate ADH. What urine and fluid-balance changes result?", "Large volumes of dilute urine occur (diabetes insipidus), and blood osmolarity can rise toward dehydration if water intake does not keep pace with losses.", "anatomy-383"],
  ["Endocrine", "Blood glucose rises sharply after a meal. Trace the hormonal response and its main effects.", "Pancreatic beta cells release insulin, which increases glucose uptake into cells and promotes glycogen synthesis in liver and muscle, lowering blood glucose.", "anatomy-384"],
  ["Muscular", "A sprinter relies heavily on anaerobic glycolysis during a short race. What metabolic byproduct builds up, and what sensation results?", "Lactate and associated hydrogen ions accumulate, contributing to the burning sensation and fatigue in the working muscle.", "anatomy-385"],
  ["Muscular", "A mutation reduces dystrophin in skeletal muscle fibers. Why does repeated contraction damage the fibers over time?", "Dystrophin normally anchors the cytoskeleton to the membrane and extracellular matrix; without it, the sarcolemma is unstable and tears more easily during contraction, causing progressive fiber damage.", "anatomy-386"],
  ["Muscular", "During a sustained isotonic contraction lifting a constant load, which sarcomere components shorten as filaments slide?", "The H zone and I band narrow as actin filaments slide further over myosin filaments; the thick and thin filaments themselves do not change length.", "anatomy-387"],
  ["Skeletal", "A child has a vitamin D deficiency. How is bone mineralization affected?", "Reduced vitamin D lowers intestinal calcium and phosphate absorption, so bone mineralizes poorly and becomes soft and prone to deformity (rickets).", "anatomy-388"],
  ["Skeletal", "A fracture tears the periosteum covering the bone. Why does this matter for healing?", "The periosteum supplies blood vessels and osteoblast precursors essential for forming the initial fracture callus, so damage to it can slow healing.", "anatomy-389"],
  ["Skeletal", "Chemotherapy suppresses red bone marrow activity. Besides immune cells, what other blood components may become deficient?", "Red blood cells and platelets may also become deficient, since red marrow produces all formed blood elements, risking anemia and bleeding alongside immunosuppression.", "anatomy-390"],
  ["Integumentary", "A pressure ulcer progresses through the dermis into subcutaneous tissue. Which skin functions are most compromised at that depth?", "Barrier protection, sensation, and local temperature regulation are significantly compromised, and infection risk rises because deeper tissue is exposed.", "anatomy-391"],
  ["Integumentary", "A homebound patient gets minimal sun exposure for months. Which integumentary-driven process is impaired, and what systemic consequence can follow?", "Cutaneous vitamin D synthesis is reduced, which can impair calcium absorption and weaken bone health over time.", "anatomy-392"],
  ["Integumentary", "On a hot day, eccrine sweat glands secrete heavily across the skin. How does evaporation of that sweat cool the body?", "Evaporating sweat absorbs heat energy from the skin surface, carrying thermal energy away from the body and lowering skin temperature.", "anatomy-393"],
  ["Reproductive", "A man has very low sperm motility on semen analysis. Which step in reproduction is most directly impaired?", "The sperm's ability to swim through the female reproductive tract and reach/penetrate the oocyte is impaired, reducing fertilization likelihood.", "anatomy-394"],
  ["Reproductive", "If implantation does not occur, the corpus luteum degenerates and stops secreting progesterone. What happens next?", "Progesterone and estrogen levels fall, the endometrial lining breaks down, and menstruation begins.", "anatomy-395"],
  ["Reproductive", "A fertilized egg implants in the uterine tube instead of the uterus. Why is this dangerous?", "An ectopic pregnancy can grow until it ruptures the narrow tube, causing internal bleeding, because the tube cannot support an expanding pregnancy.", "anatomy-396"],
  ["Reproductive", "Home pregnancy tests detect a hormone from the developing placenta. Which hormone is it, and what does a rising level indicate?", "Human chorionic gonadotropin (hCG); rising levels indicate the developing placenta is signaling the corpus luteum to keep producing progesterone, supporting the pregnancy.", "anatomy-397"],
  ["Cells", "A drug irreversibly blocks the sodium-potassium pump in a cell. What happens to its ion gradients and resting membrane potential over time?", "Sodium builds up inside and potassium leaks out without active pumping, so the ion gradients run down and the resting membrane potential depolarizes toward a less negative value.", "anatomy-398"],
  ["Cells", "A membrane is permeable only to water, and the solution on side A has a higher solute concentration than side B. Which way does water move, and why?", "Water moves from B to A by osmosis, toward the side with higher solute (lower water) concentration, increasing A's volume until equilibrium or opposing pressure is reached.", "anatomy-399"],
  ["Cells", "A cell increases production of heat-shock proteins during a febrile illness. What general role do these proteins serve?", "They help stabilize and refold stressed or misfolded proteins, protecting cellular structure and function during stress, an example of homeostasis at the cellular level.", "anatomy-400"],
  ["Forum Marathon", "A patient in septic shock has fever, rapid heart rate, low blood pressure, and reduced urine output. Connect these cardiovascular, excretory, and immune findings.", "Widespread inflammation causes vasodilation and vascular leakage, lowering blood pressure; the heart rate rises to compensate, while reduced renal perfusion lowers urine output as the kidneys conserve volume, and systemic infection drives the fever.", "anatomy-401"],
  ["Forum Marathon", "A patient with poorly controlled diabetes has excessive urination, excessive thirst, and weight loss. Connect the endocrine and excretory mechanisms.", "Insufficient insulin action leaves glucose elevated in blood; once it exceeds the renal reabsorption threshold, glucose spills into urine and draws water with it osmotically, causing excess urination and triggering thirst, while fat and protein breakdown for energy contributes to weight loss.", "anatomy-402"],
  ["Respiratory", "A patient with COPD has chronically elevated blood CO2, and their respiratory drive has shifted to depend on low oxygen rather than high CO2. What can happen if this patient receives high-concentration oxygen too quickly?", "Removing the hypoxic drive can blunt ventilatory effort, allowing CO2 to climb further, so oxygen is typically titrated carefully in this situation.", "anatomy-403"],
  ["Respiratory", "An arterial blood gas shows low pH, high CO2, and high bicarbonate. What primary disturbance and compensation pattern does this suggest?", "A respiratory acidosis from CO2 retention, with renal compensation raising bicarbonate to partially offset the falling pH.", "anatomy-404"],
  ["Respiratory", "During exercise, a person's tidal volume and respiratory rate both rise. Why does increasing tidal volume raise alveolar ventilation more efficiently than raising rate alone?", "A larger tidal volume carries relatively more fresh air past the fixed anatomical dead space to the alveoli, so each breath exchanges a greater share of air than rapid, shallow breathing would.", "anatomy-405"],
  ["Digestive", "A patient has had the gallbladder removed, and now struggles to digest large fatty meals even though the liver still makes bile. Why?", "Without gallbladder storage and concentration, bile drips continuously into the duodenum instead of being released as a concentrated bolus timed to fatty meals, reducing fat emulsification for large meals.", "anatomy-406"],
  ["Digestive", "A patient with months of poor dietary protein intake develops low blood albumin. How does the digestive/absorptive pathway explain this?", "Too little dietary protein limits the amino acids available for the liver to synthesize albumin, since protein must first be digested and absorbed before hepatic protein synthesis can use it.", "anatomy-407"],
  ["Digestive", "A duodenal ulcer damages the brush-border region where disaccharidase enzymes normally act. Which digestive step is most directly impaired?", "Final breakdown of disaccharides such as lactose or sucrose into absorbable monosaccharides is impaired, since that step depends on enzymes anchored to the damaged brush border.", "anatomy-408"],
  ["Immune", "A patient with HIV has a declining CD4+ T-helper cell count. Why does this raise susceptibility to many different infections?", "Helper T cells coordinate both humoral and cell-mediated adaptive responses, so their depletion weakens activation of B cells and cytotoxic T cells needed to control a wide range of pathogens.", "anatomy-409"],
  ["Immune", "Years after a first vaccination, a second exposure to the same antigen produces a faster, larger antibody response. Which cells explain this, and which antibody class typically dominates?", "Memory B cells enable the faster, stronger secondary response, which is typically dominated by IgG.", "anatomy-410"],
  ["Immune", "An autoimmune disorder causes immune cells to attack myelin in the central nervous system. What category of immune failure is this, and what functional problem results?", "A breakdown of self-tolerance causing autoimmune attack on self tissue; the resulting demyelination slows or blocks nerve signal conduction.", "anatomy-411"],
  ["Cardiovascular", "A patient has a stroke volume of 70 mL and a cardiac output of 4.9 L/min. Calculate their heart rate.", "4,900 mL / 70 mL = 70 beats/min.", "anatomy-412"],
  ["Cardiovascular", "A patient's ECG shows an abnormally wide QRS complex. Which part of the conduction system is most likely delayed?", "Ventricular depolarization is likely delayed, often from slowed conduction through the bundle branches or Purkinje fibers rather than the SA or AV node.", "anatomy-413"],
  ["Cardiovascular", "Atherosclerosis narrows a coronary artery, and exertion triggers chest pain that resolves with rest. Explain the mechanism.", "The narrowed vessel supplies enough oxygen for resting demand but not increased demand during exertion, so supply fails to match demand during exercise, causing ischemic pain that resolves once demand falls at rest.", "anatomy-414"],
  ["Nervous", "A patient has hypothalamic damage affecting thirst and temperature regulation but normal cognition. What does this suggest about brain organization?", "Different brain regions govern distinct functions, so a lesion limited to an autonomic/homeostatic control center can impair those specific functions while sparing higher cognitive processing elsewhere.", "anatomy-415"],
  ["Nervous", "After a mid-thoracic spinal cord injury, a patient loses voluntary motor control below the injury, but reflexes initiated below that level remain present. Why?", "Descending voluntary motor pathways are interrupted at the injury site, but local spinal reflex arcs below the lesion stay intact because they do not require input from the brain.", "anatomy-416"],
  ["Nervous", "After bilateral damage to a specific medial temporal lobe structure, a patient cannot form new long-term memories, but older memories remain intact. Which structure is implicated?", "The hippocampus, which is critical for consolidating new long-term memories but not for retrieving memories already stored elsewhere.", "anatomy-417"],
  ["Excretory", "A patient's blood urea nitrogen is elevated while creatinine stays normal. Besides early kidney disease, what else could explain this isolated BUN rise?", "Dehydration or high protein intake/catabolism can raise BUN disproportionately to creatinine, since BUN is more sensitive to hydration status and protein metabolism than creatinine is.", "anatomy-418"],
  ["Excretory", "One filtered substance is partly reabsorbed back into blood, and another is also secreted into the tubule. How do their final urine concentrations compare with their filtrate concentrations?", "The reabsorbed substance ends up less concentrated in urine than in the original filtrate, while the secreted substance ends up more concentrated in urine than in the filtrate.", "anatomy-419"],
  ["Excretory", "A medication dilates the afferent arteriole more than the efferent arteriole. What happens to glomerular filtration rate?", "GFR tends to rise, because net glomerular capillary pressure increases when afferent resistance falls relative to efferent resistance.", "anatomy-420"],
  ["Endocrine", "A pituitary tumor secretes excess growth hormone after a patient's growth plates have already closed. What condition results, and why does it differ from gigantism?", "Acromegaly; because the growth plates are already fused, excess growth hormone thickens bone and soft tissue rather than increasing height, unlike gigantism, which occurs before plate closure.", "anatomy-421"],
  ["Endocrine", "Autoimmune destruction of pancreatic beta cells occurs in a patient. Which hormone becomes deficient, and what happens to blood glucose regulation?", "Insulin becomes deficient, so cells cannot efficiently take up glucose and blood glucose rises chronically, the pattern seen in type 1 diabetes.", "anatomy-422"],
  ["Endocrine", "A patient has an abnormally high parathyroid hormone level along with high blood calcium. Trace the mechanism connecting them.", "Elevated PTH increases bone resorption, renal calcium reabsorption, and activation of vitamin D for intestinal calcium absorption, together raising blood calcium.", "anatomy-423"],
  ["Muscular", "A medication blocks calcium release from the sarcoplasmic reticulum in skeletal muscle. Which immediate contractile step fails?", "Without calcium binding troponin, tropomyosin keeps blocking myosin-binding sites on actin, so cross-bridge cycling and contraction cannot proceed even when the fiber is stimulated.", "anatomy-424"],
  ["Muscular", "An athlete is training for a marathon. Why are slow-twitch (type I) fibers better suited to this event than fast-twitch (type II) fibers?", "Slow-twitch fibers rely on oxidative metabolism, resist fatigue, and sustain prolonged submaximal contraction, matching the demands of endurance events.", "anatomy-425"],
  ["Muscular", "A weightlifter slowly lowers a heavy weight under control. What is happening to the muscle's length and tension during this phase?", "The muscle lengthens while still generating tension, resisting the load as it is lowered rather than shortening against it (an eccentric contraction).", "anatomy-426"],
  ["Skeletal", "An X-ray shows new bone bridging a recent fracture, but the bone has not yet been reshaped to its original contour. What healing stage does this represent?", "The bony callus stage, after the soft callus has been replaced by woven bone but before remodeling restores the bone's original shape and strength.", "anatomy-427"],
  ["Skeletal", "A postmenopausal woman develops reduced bone density as her estrogen levels decline. Explain the hormonal mechanism.", "Estrogen normally restrains osteoclast activity, so falling estrogen lets bone resorption outpace bone formation, lowering bone density over time.", "anatomy-428"],
  ["Skeletal", "A joint permits only limited gliding movement between adjacent bones with little rotation. What joint classification and example fit this description?", "A plane (gliding) synovial joint, such as those between carpal bones, which allows limited sliding motion.", "anatomy-429"],
  ["Integumentary", "A patch of skin has reduced melanocyte activity and cannot tan appropriately. What is the physiological consequence for that area?", "Reduced melanin leaves the patch with less protection from UV-induced DNA damage, increasing sunburn and skin-damage risk there.", "anatomy-430"],
  ["Integumentary", "A deep laceration through the epidermis and upper dermis is sutured promptly with good blood supply. What healing phase sequence is expected?", "Hemostasis, inflammation, proliferation (granulation tissue and re-epithelialization), and remodeling, in that general order.", "anatomy-431"],
  ["Integumentary", "An elderly patient's skin has thinned, with reduced subcutaneous fat and fewer sweat glands. Which homeostatic functions are most at risk?", "Thermoregulation and injury protection are most at risk, since thinner insulating fat and fewer sweat glands impair both heat conservation/dissipation and cushioning against trauma.", "anatomy-432"],
  ["Reproductive", "A couple tracking basal body temperature notices a small sustained rise partway through the cycle. What hormonal change explains this?", "Progesterone from the post-ovulation corpus luteum has a mild thermogenic effect, raising basal body temperature after ovulation occurs.", "anatomy-433"],
  ["Reproductive", "A man has a varicocele that raises the local temperature around one testis slightly above normal. Why could this affect fertility?", "Spermatogenesis is temperature-sensitive and works best below core body temperature, so elevated scrotal temperature can impair sperm production and quality.", "anatomy-434"],
  ["Reproductive", "FSH levels are used to help evaluate menopausal status. Why does FSH typically rise as ovarian function declines?", "Declining ovarian estrogen and inhibin reduce negative feedback on the pituitary, so FSH secretion rises as the body tries unsuccessfully to stimulate the failing ovaries.", "anatomy-435"],
  ["Cells", "Partial failure of the sodium-potassium pump leaves a cell's resting membrane potential less negative than normal. How does this affect the cell's excitability?", "A less negative resting potential sits closer to threshold, initially increasing excitability, but sustained depolarization can inactivate sodium channels and reduce the cell's ability to fire.", "anatomy-436"],
  ["Cells", "A researcher places animal cells into a hypertonic solution. Predict what happens and explain the direction of water movement.", "Water moves out of the cells by osmosis toward the higher extracellular solute concentration, causing the cells to shrink (crenate).", "anatomy-437"],
  ["Cells", "A cell imports glucose by facilitated diffusion, and extracellular glucose concentration suddenly drops below the intracellular level. What happens to net glucose movement?", "Net movement reverses direction, with glucose now moving out of the cell down its new concentration gradient through the same carrier proteins.", "anatomy-438"],
  ["Forum Marathon", "A patient in anaphylactic shock has widespread vasodilation, airway swelling, and a rapid, weak pulse. Connect the immune, cardiovascular, and respiratory mechanisms.", "Massive mast-cell histamine release causes systemic vasodilation and vascular leakage that drops blood pressure, bronchoconstriction and airway edema that impair breathing, and reflex tachycardia as the heart tries to compensate for falling pressure.", "anatomy-439"],
  ["Forum Marathon", "A patient with uncontrolled type 1 diabetes develops deep, rapid breathing, a fruity breath odor, and dehydration. Connect the endocrine, respiratory, and excretory findings.", "Insulin deficiency drives fat breakdown and ketone accumulation, producing metabolic acidosis; rapid deep (Kussmaul) breathing blows off CO2 to compensate, while osmotic diuresis from high blood glucose causes dehydration through the kidneys.", "anatomy-440"],
  ["Forum Marathon", "A patient with chronic kidney failure has elevated blood potassium and a widened, irregular pattern on ECG. Connect the excretory and cardiovascular findings.", "Failing kidneys cannot excrete potassium adequately, so the resulting hyperkalemia alters cardiac membrane excitability and conduction, producing ECG changes such as a widened QRS and arrhythmia risk.", "anatomy-441"],
  ["Forum Marathon", "A patient with severe hypothyroidism has a slow heart rate, low body temperature, and sluggish reflexes. Connect the endocrine, cardiovascular, and nervous/muscular findings.", "Low thyroid hormone reduces cellular metabolic rate broadly, slowing heart rate and contractility, lowering heat production, and slowing neuromuscular reflex responses.", "anatomy-442"],
  ["Respiratory", "A patient hypoventilates after receiving a respiratory depressant. Predict the initial changes in carbon dioxide and blood pH, then identify the compensating organ.", "Carbon dioxide rises and forms more carbonic acid, lowering pH in respiratory acidosis; over hours to days, the kidneys compensate by excreting hydrogen ions and retaining bicarbonate.", "anatomy-443"],
  ["Respiratory", "A pulmonary embolus blocks blood flow to ventilated alveoli. How do the local V/Q ratio and arterial oxygen change?", "Ventilation remains while perfusion falls, producing a high V/Q region and wasted ventilation; overall arterial oxygen can fall because blood must rely on the remaining perfused lung.", "anatomy-444"],
  ["Digestive", "A patient has obstructed bile flow and pancreatic lipase deficiency. Why are fat-soluble vitamin levels especially vulnerable?", "Bile is needed to emulsify fat and form micelles, while lipase digests triglycerides; losing both processes severely reduces absorption of fats and vitamins A, D, E, and K.", "anatomy-445"],
  ["Digestive", "Repeated vomiting causes loss of stomach acid. Predict the primary acid-base change and an early respiratory compensation.", "Hydrogen ion loss produces metabolic alkalosis; ventilation may decrease to retain carbon dioxide, although respiratory compensation is limited by the need for oxygen.", "anatomy-446"],
  ["Immune", "A pathogen is coated with antibody but phagocytes cannot bind the antibody's Fc region. Which defense step fails despite normal antigen recognition?", "Opsonization-dependent attachment and phagocytosis are impaired: antibody still binds antigen, but phagocytes cannot efficiently recognize and engulf the coated pathogen.", "anatomy-447"],
  ["Immune", "A patient lacks helper T cells but has functioning B cells and cytotoxic T cells. Why are both humoral and cellular adaptive responses weakened?", "Helper T-cell cytokines and co-stimulation support B-cell antibody responses and cytotoxic T-cell expansion, so both arms respond poorly despite the cells being present.", "anatomy-448"],
  ["Cardiovascular", "Blood pressure is 90/60 mmHg and heart rate is 120 beats/min after fluid loss. What does the tachycardia represent, and why may it eventually fail?", "It is sympathetic compensation intended to preserve cardiac output; severe volume loss lowers venous return and stroke volume so much that a faster rate cannot maintain perfusion.", "anatomy-449"],
  ["Cardiovascular", "Aortic valve narrowing raises left ventricular afterload. Predict the initial structural adaptation and a later functional consequence.", "The ventricle develops concentric hypertrophy to generate greater pressure; later, stiffness and oxygen demand can impair filling and eventually reduce cardiac output.", "anatomy-450"],
  ["Nervous", "A lesion causes loss of vibration and position sense in the right leg below a spinal level but preserves pain sensation. Which pathway is most likely damaged?", "The right dorsal column pathway is likely damaged because it carries ipsilateral vibration and proprioception in the spinal cord, while the spinothalamic pain pathway is spared.", "anatomy-451"],
  ["Nervous", "A drug blocks acetylcholinesterase at a neuromuscular junction. Explain why contraction first increases but prolonged exposure can cause weakness.", "Acetylcholine initially persists and repeatedly stimulates receptors; sustained depolarization then prevents normal membrane resetting, producing a depolarization block and weakness.", "anatomy-452"],
  ["Excretory", "A patient's GFR falls while aldosterone and ADH rise. Connect these findings to blood pressure and urine characteristics.", "Low renal perfusion activates volume-conserving responses; aldosterone retains sodium and ADH retains water, producing lower-volume, more concentrated urine while supporting pressure.", "anatomy-453"],
  ["Excretory", "Filtered load of glucose is 300 mg/min, but tubular transport maximum is 250 mg/min. How much glucose is excreted per minute?", "About 50 mg/min is excreted because filtration exceeds maximal reabsorption by 300 - 250 = 50 mg/min.", "anatomy-454"],
  ["Endocrine", "A pituitary tumor secretes excess ACTH. Predict cortisol, adrenal cortex size, and feedback effects on normal ACTH-producing cells.", "Cortisol rises and the adrenal cortex enlarges under ACTH stimulation; high cortisol suppresses normal hypothalamic and pituitary signaling, though the autonomous tumor may continue secreting.", "anatomy-455"],
  ["Endocrine", "A patient has low thyroid hormone and high TSH. Localize the most likely level of dysfunction and justify it.", "Primary thyroid failure is most likely: the thyroid produces too little hormone, removing negative feedback and causing the pituitary to raise TSH.", "anatomy-456"],
  ["Muscular", "A motor unit is recruited more frequently during a lift. How do recruitment and temporal summation jointly increase force?", "Recruitment activates more muscle fibers, while higher firing frequency prevents complete relaxation and sums tension within active fibers; together they raise total force.", "anatomy-457"],
  ["Skeletal", "Parathyroid hormone remains elevated for months. Predict effects on blood calcium and bone remodeling.", "Blood calcium is supported or increased through renal and skeletal actions, while persistent signaling favors bone resorption and can reduce bone mass.", "anatomy-458"],
  ["Integumentary", "A patient with extensive burns develops hypothermia despite a warm room. Which lost skin functions explain this?", "Barrier loss increases evaporative water and heat loss, while damaged dermal vessels and insulation impair controlled heat conservation and distribution.", "anatomy-459"],
  ["Reproductive", "FSH is low, LH is low, and gonadal hormones are low. Is primary gonadal failure or central dysfunction more likely?", "Central hypothalamic or pituitary dysfunction is more likely because inadequate gonadotropins accompany low gonadal hormones; primary gonadal failure usually raises FSH and LH.", "anatomy-460"],
  ["Cells", "A cell is deprived of oxygen, ATP falls, and the sodium-potassium pump slows. Trace how this can produce cellular swelling.", "Intracellular sodium accumulates when active transport fails; water follows osmotically, causing the cell and organelles to swell.", "anatomy-461"],
  ["Forum Marathon", "A patient with heart failure develops ankle edema, shortness of breath, and reduced kidney perfusion. Connect all three findings.", "Poor cardiac output lowers renal perfusion and activates sodium-water retention; elevated venous pressure drives peripheral edema, while pulmonary vascular pressure promotes lung fluid and breathlessness.", "anatomy-462"],
  ["Respiratory", "A patient has pH 7.30, PaCO2 30 mmHg, and HCO3- 15 mEq/L. Identify the primary disturbance and the compensatory response, and explain why the compensation is incomplete.", "Metabolic acidosis is primary, since both pH and HCO3- are low; the lungs compensate by hyperventilating to lower PaCO2 toward the expected range, but pH remains below normal because respiratory compensation blunts the acidosis without fully correcting it.", "anatomy-463"],
  ["Respiratory", "During strenuous exercise, cardiac output rises sharply and nearly equalizes blood flow across the lung apex and base. How does this change the normal resting V/Q gradient, and what is the net effect on gas exchange?", "At rest the apex has a higher V/Q than the base because it is relatively overventilated and underperfused; rising pulmonary blood flow during exercise recruits apical capillaries and evens perfusion, narrowing the V/Q gradient and improving overall gas-exchange efficiency at high demand.", "anatomy-464"],
  ["Respiratory", "A patient with emphysema has increased lung compliance but loses the elastic recoil needed to keep small airways open during exhalation. Explain how this produces air trapping and why pursed-lip breathing helps.", "Loss of elastic recoil lets small airways collapse during passive exhalation, trapping air behind them; pursed-lip breathing creates back-pressure that splints the airways open longer, allowing more complete exhalation before collapse occurs.", "anatomy-465"],
  ["Respiratory", "During intense exercise, muscle tissue becomes more acidic and warmer than at rest. Explain how these two local changes affect hemoglobin's oxygen affinity and why this benefits the exercising muscle.", "Increased acidity and heat both shift the oxygen-hemoglobin dissociation curve to the right, lowering hemoglobin's oxygen affinity so more oxygen is released to the metabolically active, oxygen-demanding muscle.", "anatomy-466"],
  ["Cardiovascular", "A vessel's radius decreases by half from atherosclerotic narrowing, while pressure gradient and length stay constant. Using the radius-flow relationship, predict the change in flow and its clinical significance.", "Flow is proportional to radius to the fourth power, so halving the radius reduces flow to about 1/16 of its original value; this steep sensitivity explains why modest further narrowing of an already-stenotic vessel can cause a large, clinically significant drop in flow.", "anatomy-467"],
  ["Cardiovascular", "A patient loses 20% of blood volume from hemorrhage. Trace the short-term baroreceptor response and the slower renin-angiotensin-aldosterone response that follow, and explain why both are needed.", "Baroreceptors sense falling pressure within seconds and raise sympathetic output, increasing heart rate, contractility, and vasoconstriction for immediate support; over minutes to hours, reduced renal perfusion activates renin, generating angiotensin II and aldosterone that restore blood volume more durably once the rapid neural response alone is insufficient.", "anatomy-468"],
  ["Cardiovascular", "A failing heart's ventricle operates on the flattened portion of the Frank-Starling curve. Explain why further volume loading fails to increase stroke volume and may worsen symptoms.", "On the flattened portion, additional preload no longer meaningfully stretches the overstretched, weakened myocardium to increase contractile force, so stroke volume plateaus while the added volume raises venous and pulmonary pressures, worsening congestion.", "anatomy-469"],
  ["Cardiovascular", "One patient has a wide pulse pressure from a stiff, non-compliant aorta, while another has the same wide pulse pressure from aortic valve regurgitation. Explain how each mechanism independently widens pulse pressure.", "A stiff aorta cannot buffer systolic ejection as effectively, raising systolic pressure while diastolic pressure is largely unaffected; aortic regurgitation lets blood leak back into the ventricle during diastole, lowering diastolic pressure while increased stroke volume raises systolic pressure, so both reach a similar wide pulse pressure through different mechanisms.", "anatomy-470"],
  ["Nervous", "A patient has right-sided facial weakness that spares the forehead muscles, plus right-sided arm and leg weakness. Localize the lesion and explain the forehead sparing.", "An upper motor neuron lesion above the facial nucleus, likely in the left motor cortex or corticobulbar tract affecting the right side after decussation; forehead muscles receive bilateral upper motor neuron innervation, so they are spared while the rest of the face and body are affected.", "anatomy-471"],
  ["Nervous", "A patient loses pain and temperature sensation bilaterally below a spinal level after a vascular event, while vibration and proprioception remain intact. Identify the vascular territory and cord region affected.", "The anterior spinal artery territory is affected: infarction damages the anterior two-thirds of the cord, including the bilateral spinothalamic tracts, while the posterior spinal artery-supplied dorsal columns are spared, preserving vibration and proprioception (anterior cord syndrome).", "anatomy-472"],
  ["Nervous", "A patient cannot voluntarily move the left arm and leg, but reflexes are present and become more brisk over weeks, with increased muscle tone. Classify the lesion type and explain the tone finding.", "An upper motor neuron lesion; loss of descending inhibitory input to spinal reflex circuits increases reflex excitability and muscle tone (spasticity) over time, unlike a lower motor neuron lesion, which would cause reduced tone and absent reflexes.", "anatomy-473"],
  ["Nervous", "A patient has resting tremor, rigidity, and slowed movement initiation, with no weakness on strength testing. Which neural circuit is most likely affected, and why does strength remain normal?", "The basal ganglia dopaminergic circuit is most likely affected; this circuit modulates movement initiation and tone rather than generating muscle force directly, so corticospinal strength pathways and raw strength remain intact.", "anatomy-474"],
  ["Excretory", "A dehydrated patient has persistently dilute urine despite high plasma osmolality. Which part of the ADH pathway is most likely failing, and how would giving desmopressin distinguish the two possible causes?", "A failure of ADH secretion or renal response (diabetes insipidus) is likely; desmopressin will concentrate the urine in central diabetes insipidus (pituitary ADH deficiency) but will not in nephrogenic diabetes insipidus (renal resistance to ADH), distinguishing the two.", "anatomy-475"],
  ["Excretory", "A patient on a thiazide diuretic develops hyponatremia. Trace how reduced distal sodium reabsorption combined with persistent ADH secretion produces low blood sodium.", "Thiazides impair distal tubule sodium reabsorption, causing mild volume contraction; the resulting volume depletion stimulates ADH release, which increases water reabsorption in the collecting duct disproportionately to sodium, diluting plasma sodium and producing hyponatremia.", "anatomy-476"],
  ["Excretory", "Increased NaCl delivery to the macula densa activates tubuloglomerular feedback. Explain the resulting changes in afferent arteriole tone and glomerular filtration rate, and why this protects the nephron.", "High macula densa NaCl triggers afferent arteriole constriction, lowering glomerular capillary pressure and GFR; this negative feedback reduces filtered load back toward normal, protecting the nephron from sustained excessive solute and fluid delivery.", "anatomy-477"],
  ["Excretory", "A patient hyperventilates for a prolonged illness, lowering PaCO2 chronically. Predict the renal compensatory change in bicarbonate handling and the resulting acid-base pattern.", "Chronic respiratory alkalosis prompts the kidneys to excrete more bicarbonate and retain hydrogen ions, lowering plasma bicarbonate to partially normalize pH despite the persistently low PaCO2.", "anatomy-478"],
  ["Endocrine", "A pituitary adenoma secretes excess TSH despite normal initial thyroid hormone levels. Explain the expected feedback abnormality and the eventual thyroid hormone trend.", "The tumor secretes TSH autonomously rather than in response to feedback, so it escapes normal negative-feedback suppression by thyroid hormone; thyroid hormone levels will rise as the gland is persistently overstimulated, unlike the suppressed TSH seen in primary thyroid hormone excess.", "anatomy-479"],
  ["Endocrine", "Patient A has low cortisol and high ACTH; Patient B has low cortisol and low ACTH. Localize each dysfunction and justify the ACTH pattern.", "Patient A has primary adrenal insufficiency: a failing adrenal gland produces too little cortisol, removing negative feedback and driving ACTH up. Patient B has secondary insufficiency: inadequate pituitary ACTH itself causes low cortisol, so ACTH is low rather than compensatorily elevated.", "anatomy-480"],
  ["Endocrine", "A parathyroid adenoma causes chronically high PTH, high calcium, and low phosphate. Explain the mechanism producing the low phosphate while calcium rises.", "PTH increases renal phosphate excretion by reducing its proximal tubule reabsorption, even as it raises calcium through bone resorption, renal calcium reabsorption, and vitamin D activation, so phosphate falls while calcium rises.", "anatomy-481"],
  ["Endocrine", "A patient takes exogenous glucocorticoids long-term, then stops abruptly. Explain why acute adrenal insufficiency can result despite structurally intact adrenal glands.", "Chronic exogenous glucocorticoids suppress hypothalamic CRH and pituitary ACTH through negative feedback, causing adrenal cortical atrophy from disuse; abrupt cessation leaves both insufficient endogenous cortisol and a suppressed HPA axis unable to respond quickly, risking adrenal crisis.", "anatomy-482"],
  ["Immune", "A patient with a C5-C9 complement deficiency has recurrent Neisseria infections but normal responses to most other bacteria. Explain the mechanistic link.", "C5-C9 form the membrane attack complex, which is especially important for lysing gram-negative Neisseria species; other bacteria remain controlled by opsonization and phagocytosis from earlier complement components and antibodies, which stay intact.", "anatomy-483"],
  ["Immune", "A patient's B cells class-switch normally, but their antibodies show no increase in binding affinity over repeated exposures. Which germinal center process is most likely impaired?", "Somatic hypermutation and affinity maturation are likely impaired; class switching can occur independently, but without iterative mutation and selection in germinal centers, antibody affinity does not improve across exposures.", "anatomy-484"],
  ["Immune", "One patient develops joint pain and kidney inflammation from circulating antigen-antibody complexes depositing in tissue, while another develops a delayed skin reaction 48 hours after allergen contact with no antibody involvement. Classify each hypersensitivity type and the key mechanistic difference.", "The first is Type III (immune complex) hypersensitivity, driven by antigen-antibody complex deposition and complement-mediated inflammation; the second is Type IV (delayed, cell-mediated) hypersensitivity, driven by sensitized T cells rather than antibodies, explaining its delayed onset.", "anatomy-485"],
  ["Muscular", "During the first 10 seconds of maximal sprinting, muscle relies primarily on the phosphagen system; after about 30-40 seconds, anaerobic glycolysis dominates. Explain why the energy system shifts and what byproduct accumulates in the second phase.", "Stored ATP and creatine phosphate deplete within seconds, so muscle shifts to anaerobic glycolysis for faster, though less efficient, ATP regeneration without oxygen, producing lactate and hydrogen ions that contribute to fatigue.", "anatomy-486"],
  ["Muscular", "A trained endurance athlete has a higher proportion of type I fibers with greater mitochondrial density and capillary supply than an untrained person. Explain how these three adaptations jointly improve sustained aerobic performance.", "More mitochondria increase oxidative ATP production capacity, greater capillary density improves oxygen and substrate delivery and removal, and a higher type I fiber proportion favors fatigue-resistant oxidative metabolism, together supporting prolonged submaximal effort without early fatigue.", "anatomy-487"],
  ["Muscular", "A muscle is stretched rapidly before an explosive contraction, as in a countermovement jump. Explain how elastic energy storage and the stretch reflex both contribute to greater force output than a contraction starting from rest.", "The rapid stretch loads elastic tendon and titin components that recoil to add mechanical energy, while the stretch reflex triggers additional motor neuron activation through muscle spindles, so passive elastic recoil and reflexive neural drive together increase force beyond a purely concentric contraction.", "anatomy-488"],
  ["Skeletal", "A long bone experiences increased mechanical loading during resistance training. Trace how osteocytes sense this strain and the resulting shift between osteoblast and osteoclast activity.", "Osteocytes detect increased strain through their canalicular network and reduce sclerostin secretion, lessening inhibition of osteoblast activity; this shifts remodeling toward bone formation over resorption, increasing bone density in line with Wolff's law.", "anatomy-489"],
  ["Skeletal", "A child's growth plate shows orderly zones of resting, proliferating, hypertrophic, and calcifying cartilage, but a tumor disrupts the proliferating zone specifically. Predict the effect on bone elongation versus bone width.", "Longitudinal growth is most impaired because the proliferating zone generates new chondrocytes that drive length increase, while appositional growth from the periosteum, which affects bone width, can continue largely independent of this zone.", "anatomy-490"],
  ["Integumentary", "In a hot environment, cutaneous arterioles dilate and sweat glands activate, but a patient taking an anticholinergic medication cannot sweat normally. Explain the resulting thermoregulatory risk despite normal vasodilation.", "Vasodilation alone increases radiant and convective heat loss only when ambient temperature is below skin temperature; without evaporative cooling from sweating, heat loss is insufficient in very hot conditions, risking dangerous hyperthermia even with normal skin blood flow.", "anatomy-491"],
  ["Integumentary", "During cold exposure, a person first shivers, then later relies on non-shivering thermogenesis if sufficient brown adipose tissue is present. Compare the two mechanisms' heat-generation strategies.", "Shivering generates heat through rapid, repeated skeletal muscle contractions that waste most contractile energy as heat; non-shivering thermogenesis uses uncoupling protein in brown fat mitochondria to dissipate the proton gradient directly as heat without ATP-driven movement.", "anatomy-492"],
  ["Reproductive", "Elite endurance athletes with very low energy availability often develop suppressed GnRH pulsatility and amenorrhea. Trace the hormonal cascade from energy deficit to menstrual disruption.", "Severe energy deficit suppresses hypothalamic GnRH pulse generation, lowering LH and FSH release; reduced gonadotropins decrease ovarian estrogen production, disrupting the cyclic feedback needed for follicular development, ovulation, and menstruation.", "anatomy-493"],
  ["Reproductive", "In the mid-cycle, rising estrogen from a maturing follicle switches the hypothalamic-pituitary response from suppressing to stimulating LH release. Explain this shift from negative to positive feedback and its functional purpose.", "Sustained high estrogen from the dominant follicle changes the feedback from negative to positive, triggering an LH surge that is required to complete oocyte maturation and trigger ovulation.", "anatomy-494"],
  ["Reproductive", "After ovulation, a corpus luteum secretes progesterone, which suppresses GnRH, LH, and FSH. If fertilization and implantation do not occur, trace the hormonal sequence leading back to menstruation and a new follicular phase.", "Without hCG support from an implanting embryo, the corpus luteum degenerates; progesterone and estrogen fall, releasing the pituitary and hypothalamus from negative feedback, the endometrium sheds from lost hormonal support, and rising FSH recruits a new cohort of follicles.", "anatomy-495"],
  ["Cells", "A cell's sodium-potassium pump functions normally, but a separate mutation blocks potassium leak channels in the membrane. Predict the effect on resting membrane potential.", "Resting membrane potential becomes less negative (depolarized), because reduced potassium permeability weakens the membrane's ability to stay near the potassium equilibrium potential that normally sets the resting potential.", "anatomy-496"],
  ["Cells", "A cell is exposed to a solution that is isosmotic but hypotonic because much of its solute is urea, which freely crosses the membrane. Predict the net water movement and final cell volume.", "Because urea freely permeates the membrane, it does not sustain an effective osmotic gradient; water movement instead follows the non-permeating solute difference, so despite equal total osmolarity, the solution behaves hypotonically and the cell swells.", "anatomy-497"],
  ["General", "A patient's negative-feedback thyroid loop and positive-feedback oxytocin loop during labor are both functioning normally. Explain why only one of these loops is self-limiting.", "Negative feedback (thyroid) counteracts the initial change and stabilizes a variable near a set point, making it inherently self-limiting; positive feedback (oxytocin in labor) amplifies the initial stimulus until a defined endpoint such as delivery is reached, requiring an external endpoint rather than self-correction to stop.", "anatomy-498"],
  ["Forum Marathon", "A patient with long-standing poorly controlled hypertension develops left ventricular hypertrophy, followed by reduced glomerular filtration rate and microalbuminuria. Connect the cardiovascular and renal mechanisms.", "Chronic elevated afterload drives concentric left ventricular hypertrophy; sustained systemic hypertension also damages glomerular capillaries, impairing filtration barrier integrity and reducing GFR while allowing protein leakage, showing how one upstream pressure problem damages both organs.", "anatomy-499"],
  ["Forum Marathon", "A patient in diabetic ketoacidosis has metabolic acidosis, hyperventilation, dehydration, and hyperkalemia despite total-body potassium depletion. Connect the endocrine, respiratory, excretory, and electrolyte findings.", "Insulin deficiency drives lipolysis and ketoacid production causing metabolic acidosis; compensatory Kussmaul hyperventilation lowers CO2; osmotic diuresis from hyperglycemia causes dehydration and true renal potassium loss, yet acidosis shifts potassium out of cells, producing deceptively high serum potassium despite a total-body deficit.", "anatomy-500"],
  ["Forum Marathon", "A patient with cirrhosis develops low serum albumin, peripheral edema, and ascites, along with reduced effective circulating volume that activates aldosterone. Connect the hepatic, cardiovascular, and renal mechanisms.", "Impaired hepatic protein synthesis lowers plasma albumin and oncotic pressure, letting fluid shift into tissue and the peritoneal cavity; the resulting drop in effective circulating volume activates the renin-angiotensin-aldosterone system, promoting sodium and water retention that can worsen fluid accumulation.", "anatomy-501"],
  ["Forum Marathon", "A patient with severe COPD develops chronic hypoxemia, leading to pulmonary vasoconstriction, right ventricular hypertrophy, and eventually systemic venous congestion with peripheral edema. Connect the respiratory and cardiovascular mechanisms across this progression.", "Chronic alveolar hypoxia triggers widespread hypoxic pulmonary vasoconstriction, raising pulmonary vascular resistance; the right ventricle hypertrophies to pump against this higher afterload, and eventual right-heart failure raises systemic venous pressure, causing peripheral edema and venous congestion.", "anatomy-502"],
];

export const ANATOMY_PHYSIOLOGY_DECK: Flashcard[] = cards.map(([category, front, back, id]) => ({
  id,
  category,
  front,
  back,
  source: category === "Forum Marathon"
    ? `${source}; prompt from Scioly.org Anatomy Question Marathon/forum discussion`
    : source,
}));
